  var FT = root.CALR_FULLTEXT = root.CALR_FULLTEXT || {};
  FT["BN-CAP-84-N-2-2015-NOTIFICATION-OF-APPOINTMENT-AS-REGIST-9D984D"] = {"id":"BN-CAP-84-N-2-2015-NOTIFICATION-OF-APPOINTMENT-AS-REGIST-9D984D","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":1,"structureMode":"WHOLE","title":{"zh":"N 2 2015 版依第 31 条作出的合作社登记官任命公告","en":"N 2 2015 ED NOTIFICATION OF APPOINTMENT AS REGISTRAR OF CO OPERATIVE SOCIETIES UNDER SECTION 31","orig":"N 2 2015 ED NOTIFICATION OF APPOINTMENT AS REGISTRAR OF CO OPERATIVE SOCIETIES UNDER SECTION 31","vi":"Sắc lệnh Công bố bổ nhiệm Đăng ký viên hợp tác xã","th":"คำสั่งประกาศการแต่งตั้งนายทะเบียนสหกรณ์","id":"Perintah Pemberitahuan Pengangkatan Pendaftar Koperasi","ms":"Perintah Pemberitahuan Pelantikan Pendaftar Koperasi"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《CAP-84-N-2-2015-ED-NOTIFICATION-OF-APPOINTMENT-AS-REGISTRAR-OF-CO-OPERATIVE-SOCIETIES-UNDER-SECTION-31.pdf》（3 页），本次切分 1 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"CAP-84-N-2-2015-ED-NOTIFICATION-OF-APPOINTMENT-AS-REGISTRAR-OF-CO-OPERATIVE-SOCIETIES-UNDER-SECTION-31.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-CAP-84-N-2-2015-NOTIFICATION-OF-APPOINTMENT-AS-REGIST-9D984D-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"CO-OPERATIVE SOCIETIES ACT (CHAPTER 84)\n\nNOTIFICATION OF APPOINTMENT AS\n\nREGISTRAR OF CO-OPERATIVE SOCIETIES UNDER SECTION 3(1) GN 514/1996\n\nREVISED EDITION 2015\n\nLAWS OF BRUNEI Co-operative Societies CAP. 84, N 2 1 [Subsidiary]\n\nSUBSIDIARY LEGISLATION Notification of appointment as Registrar of Co-operative Societies under section 3(1) His Majesty the Sultan and Yang Di-Pertuan has appointed the Director of Brunei Industrial Development Authority as Registrar of Co-operative Societies with effect from 18th July 1996."}}],"pack":"bn-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"N 2 2015 ED NOTIFICATION OF APPOINTMENT AS REGISTRAR OF CO OPERATIVE SOCIETIES UNDER SECTION 31","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES"] = {"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":51,"structureMode":"SECTION","title":{"zh":"R 1 2015 版合作社规则","en":"R 1 2015 ED CO OPERATIVE SOCIETIES RULES","orig":"R 1 2015 ED CO OPERATIVE SOCIETIES RULES","vi":"Quy tắc Hợp tác xã","th":"ข้อกำหนดสหกรณ์","id":"Peraturan Koperasi","ms":"Kaedah Koperasi"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《CAP-84-R-1-2015-ED-CO-OPERATIVE-SOCIETIES-RULES.pdf》（26 页），本次切分 51 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"CAP-84-R-1-2015-ED-CO-OPERATIVE-SOCIETIES-RULES.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"These Rules may be cited as the Co-operative Societies Rules."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In these Rules, “the Act” means the Co-operative Societies Act. Register of Co-operative Societies."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"The Registrar shall keep or cause to be kept at his office a register to be called “Register of Co-operative Societies” wherein shall be entered particulars relating to the registration of societies and their by-laws. Entries to be signed and alterations initialled by Registrar."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"(1) All original entries in the Register of Co-operative Societies shall be made by, or under the direction of, the Registrar and shall be signed by him.\n\n(2) Every alteration, interlineation or erasure in the Register of Co-operative Societies shall be initialled by the Registrar. Register open to inspection."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"The Register of Co-operative Societies shall be open to inspection by the public at all reasonable times and free of charge. Application for registration."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Every application for registration of a society shall be submitted to the Registrar in Form A in the Second Schedule. Copies of by-laws to accompany application for registration."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"(1) The application shall be accompanied by three copies of the proposed by-laws of the society and by the minutes of the meeting at which the members agreed to accept all the rights, duties and liabilities prescribed by the by-laws. The copies of the by-laws must be signed by the applicants for the registration and the minutes must be signed by at least ten members of the society.\n\n(2) Where the Registrar decides to register the society in Form B in the Second Schedule, the society shall be registered in the Register of Co-operative Societies. One copy of the by-laws shall be retained in the Registrar’s office and the other two shall be signed by the Registrar and returned to the society together with the certificate of registration and a copy of the Act and the rules free of charge. Signature of applicant on behalf of registered society."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"In any case where an applicant is a registered society, the application for registration and the copies of the by-laws submitted therewith under these Rules shall be signed on its behalf by the officer or officers who is or who are empowered by the by-laws of such society to sign documents on its behalf. Return of application for correction."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"If the application of the by-laws are not in conformity with the Act and the rules, the Registrar may return them and direct any necessary alteration to be made in them. Refusal to register."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"In every case where the Registrar refuses to register a society, he shall record in writing his reasons for doing so and communicate his decision to the applicant."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"The by-laws of the proposed society shall contain in respect of such of the following matters as the circumstances in each case shall require, namely —\n\n(a) the name and registered address of the society;\n\n(b) the area of its operation;\n\n(c) the objects for which the society is established and the purpose to which its funds may be applied;\n\n(d) the qualifications required for membership and the terms for admission\n\n(e) the rights and liabilities of members;\n\n(f) the manner in which the capital may be raised;\n\n(g) the mode of appointment, suspension and removal of the committee and officers, and the duties and powers of such committee and officers;\n\n(h) the mode of summoning and conducting meetings and the right of\n\n(i) the general conduct of the business of the society;\n\n(j) the rates of interest at which the society may make loans to members;\n\n(k) the disposal of profits; and\n\n(l) the authorisation of an officer or officers to sign documents on behalf of Amendment of by-laws."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"(1) After the registration of a society and its by-laws, the society may amend the by-laws in Form C in the Second Schedule subject to the following provisions —\n\n(a) every such amendment shall be made only in accordance with a resolution passed by a majority at a general meeting of the society;\n\n(b) not less than 15 days’ notice shall be given of such general meeting; and\n\n(c) not less than half of the members of the society shall be present at such Provided that in the case of non-agricultural societies to which this provision may, by written order of the Registrar, be declared to apply, one quarter of the members or one hundred members, whichever is less, present at the meeting shall be sufficient for the amendment of by-laws, but no by-laws shall be amended under the provision unless two-thirds of the members present vote in favour of the proposal.\n\n(2) Three copies of such amendments to the by-laws and one copy of the resolution of the general meeting passing the amendments shall be submitted to the Registrar with an application for the registration of the amended by-laws; such application shall be signed by the chairman and two members of the committee and shall contain information as to —\n\n(a) the date of the general meeting at which the amendments were passed;\n\n(b) the number of days’ notice given to convene the general meeting;\n\n(c) the total number of members in the society at the date of such general\n\n(d) the number of members present at the meeting;\n\n(e) the number of members who voted in support of the amendments.\n\n(3) If the Registrar approves the amendments he shall register them, retain one copy in his office and return the other two to the society duly certified by him. Register of members and nominees."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Every registered society shall keep a register to be called “Register of Members and Nominees” wherein shall be entered —\n\n(a) the name, address and occupation of each member;\n\n(b) the date on which each member’s name was entered in the register;\n\n(c) the date on which any member ceased to be a member; and\n\n(d) the nominee, if any, appointed under rule 19. To keep accounts, books and publish balance sheets."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"Every registered society shall keep such accounts and books as may from time to time be prescribed or approved by the Registrar and shall publish balance sheets annually in such manner as the Registrar may prescribe. Admission to membership."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"(1) The election and admission of members to a registered society, other than original members, shall be in such manner and on such conditions as the by-laws shall\n\n(2) An entrance fee of an amount to be prescribed in the by-laws shall be payable by every member.\n\n(3) No person shall be admitted to membership of a registered society who —\n\n(a) does not satisfy the requirements of the Act;\n\n(b) is legally or mentally disabled;\n\n(c) is a bankrupt;\n\n(d) against whom a conviction stands of an offence punishable with\n\n(e) in the case of a registered society with unlimited liability, who is already a member of another registered society with unlimited liability.\n\n(4) Any member who may at any time be found to be disqualified for any of the reasons mentioned in sub-rule (3) shall be removed from the society but without prejudice to any liabilities of person under section 28(1).\n\n(5) In case of doubt, the decision of the Registrar as to whether a person is, or is not, eligible for membership of a registered society shall be final.\n\n(6) Every person before being admitted to the membership of a registered society shall sign a declaration that he will be bound by the existing by-laws of the society, and by any modification of, or addition to, such by-laws that may be legally effected during the period of his membership. A person who is already a member by reason of his having joined the application for the registration of the society shall be required, under pain of expulsion if he refuses, to sign such declaration within one month of registration. Withdrawal from society."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Any member may withdraw from a registered society by giving written notice to the secretary but such withdrawal shall be without prejudice to section 28(1). Expulsion from society."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"If a member acts in contravention of the rules or by-laws or acts in any way detrimental to the interests of the registered society such member may be expelled by a vote of two-thirds of the members present at a general meeting upon a charge communicated to him in writing by the committee not less than one week before the meeting. Such member shall be entitled to be heard in his own defence but shall not be entitled to vote on the motion; such expulsion shall, however, be without prejudice to section 28(1). Withdrawal from society holding deposit or loans from non-members."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"In the case of any registered society of limited liability holding deposits or loans from non-members, no member withdrawing, removed or expelled therefrom shall be entitled, unless the consent of the Registrar be first obtained, to repayment of any money paid by him towards the purchase of shares except on the dissolution of the registered society as provided in Part VII of the Act."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"(1) Any member of a registered society may in writing in the presence of at least two witnesses attesting the same or by a declaration duly made, nominate any person or persons to whom his share or interest or the value of such share or interest and all other monies referred to in section 17 that may be due to him may, on the death of such member, be paid or transferred under the provision of that section, and may in similar manner revoke or vary such nomination. In such cases, the value of the member’s share or interest shall be represented by the sum actually paid by the member to acquire such share or interest unless the by-laws provide for calculation thereof otherwise.\n\n(2) In any case where more than one nominee is appointed by any member, the number of shares to be transferred or the exact proportion of the amount available that is to be transferred to each of these nominees shall be specified at the time of the\n\n(3) Every appointment of nominees shall be recorded in the Register of Members and Nominees.\n\n(4) The nominee may become a member of the society only if admitted in accordance with the by-laws.\n\n(5) Where any money is paid to a nominee who is a minor, a receipt given either by the minor or his guardian shall be sufficient discharge to the registered society. Power to deal with property of insane members."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Where a member or person claiming through a member of a registered society is insane, and no committee of his estate or trustee of his property has been duly appointed, the society may, when it is proved to the satisfaction of the Committee that it is just and expedient to do so, pay or transfer the share or interest of such member or the value of such share or interest or all other monies referred to in section 17 to any person whom they shall judge proper to receive the same on his behalf, whose receipt shall be a good discharge to the society for any sum so paid. In such cases, the value of the member’s share or interest shall be represented by the sum actually paid by the member to acquire such share or interest unless the by-laws provide for calculation thereof"}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"(1) The supreme authority in a registered society shall be vested in the general meeting of members at which every member has a right to attend and vote on all questions. At least 7 days notice shall be given before any such general meeting is held. Subject to the provisions of section 24, each member shall have one vote only which shall be exercised in person and not by proxy.\n\n(2) A general meeting shall be convened in accordance with these Rules and the by-laws of the society.\n\n(3) Subject to rule 12(1), when a registered society consists of —\n\n(a) not more than forty members, one-half of the members or ten members, whichever is the less, shall form a quorum for the purpose of the annual or a special general meeting; and\n\n(b) more than forty members, one-fourth of the total number of the members of such society or fifty members shall form a quorum for the purposes of the annual or special general meeting. If within one hour after the time fixed for any meeting the members present are not sufficient to form a quorum, the meeting shall be considered as dissolved if convened on the demand of members; in all other cases it shall stand adjourned to the same day in the next week at the same time and place and a notice to that effect shall he posted by the secretary within 24 hours, and if at the adjourned quorum is not present within one hour from the time appointed for the meeting, the members present shall form a quorum. Summoning of general meeting by Registrar."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"(1) Notwithstanding anything contained in these Rules or in the by-laws of a registered society as to the mode of summoning a general meeting, and the object, time and place of such meeting, the Registrar or any person authorised by the Registrar may summon at any time a special general meeting of the society in such manner and at such time and place as he may direct, and may specify what matters shall he discussed by the meeting. Such meeting will have all the powers of and be subject to the same rules as a general meeting called according to these Rules or the by-laws of the society.\n\n(2) A quorum for the purposes of any meeting summoned by the Registrar under sub-rule (1) shall be the same as that prescribed by the by-laws of a society for an ordinary general meeting of such society: Provided that if, at any such meeting, there are not sufficient members present to quorum, the Registrar may proceed to summon a further general meeting of the society in accordance with this rule, and at such further general meeting, any members present shall be deemed to form a quorum. Maximum liability."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"(1) Every registered society shall fix at a general meeting the maximum liability it may incur in loans or deposits whether from members or non-members.\n\n(2) The maximum so fixed shall be subject to the sanction of the Registrar, who may at any time reduce it. No registered society shall receive loans or deposits which will make its liability exceed the limit sanctioned by the Registrar. Issue of bonds or debentures."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"The issue of bonds and debentures by a registered society shall be subject to such conditions as the Registrar may prescribe."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"All monies in excess of the amount to be kept in hand as approved by the Committee shall be deposited in a bank. All cheques shall be signed by the chairman or treasurer and the secretary or another member of the committee approved by the Investments in lands and buildings."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"With the previous sanction of the Registrar, any society may invest its funds or a portion thereof in the purchase or leasing of land or in the construction of buildings or in such other manner as may be necessary for the conduct of its business and the welfare of the cooperative movement."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"Every registered society shall be liable to pay such audit fees as the Registrar may Division of profits."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"(1) Unless otherwise authorised by the Minister under the proviso to section 33(1), no dividend or payment on account of profits shall be made by a society registered with unlimited liability.\n\n(2) No registered society shall pay a dividend if the rate of interest on loans granted by it to its members exceed 10 per cent per annum.\n\n(3) No registered society shall pay a rate of dividend on shares exceeding 6 per cent per annum without the sanction of the Registrar.\n\n(4) A bonus on wages or on the value of the products of a member, or a bonus or rebate on patronage calculated in proportion to the amount of the business done by each member with the registered society may be distributed periodically to the members from surplus funds after deduction of all expenditure and after making provision for bad and doubtful debts and making allocation to the reserve fund. Election of committee."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"(1) The committee shall be elected at the annual general meeting of the registered society and shall hold office until the election of a new committee and they shall be eligible for re-election unless the by-laws of the society provide otherwise.\n\n(2) The committee shall elect the chairman, secretary and treasurer from amongst themselves immediately after the general meeting.\n\n(3) A member of the committee shall not, except with the written permission of the Registrar, hold any office of profit in the society or receive any remuneration from the funds of the society.\n\n(4) Where annual profits permit, a member of the committee may, with the approval in writing of the Registrar, be awarded an honorarium by a general meeting. Appointment of employees."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"(1) The committee may appoint the necessary employees for the conduct of the society’s business and may suspend or terminate them.\n\n(2) The committee shall have power to fix the duties and remuneration for such employees and may require them to provide security in such amount as considered reasonable or as directed by the Registrar.\n\n(3) No appointment, suspension or termination of service made under sub-rule (1) shall be valid and effective and no remuneration fixed under sub-rule (2) shall be payable and recoverable unless approved in writing by the Registrar. Disposal of produce to or through registered society."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"(1) Every member of a Marketing Society shall deliver to the society at such place as the committee shall direct, such amount of articles produced or obtained by him as may be prescribed by the by-laws or in the relevant contract to be disposed of by the\n\n(2) Any member who is proved or adjudged in accordance with section 48 to be guilty of a breach of the by-laws or the relevant contract, as the case may be, shall pay to the society as liquidated damages such sum as may be specifically assessed or ascertained in manner prescribed by the by-laws or by the relevant contract, and such sum shall be deemed to be a debt due to the society. Application for loan."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Members who desire to obtain a loan shall submit an application to the committee stating the amount and the purpose for which the loan is required, the terms of repayment and the names of the proposed sureties or any other security which is offered. Proceeding with regard to loan at committee meeting."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A33","no":33,"noLabel":{"en":"Section 33."},"text":{"en":"(1) The committee shall consider at a meeting every application for a loan and if the committee is satisfied with the trustworthiness of the applicant, the sufficiency of the security offered and the prospects of advantages to the borrower, in the way of increased production or economy or otherwise, it may sanction the loan.\n\n(2) No person other than members of the committee and the Registrar and his staff shall be present at any meeting of the committee when an application for a loan is under consideration. A member of the committee who applies for a loan or who is proposed as surety for a loan must withdraw while the relevant application is being considered. If there is a difference of opinion concerning the granting of a loan, the voting shall be taken by ballot. The proceedings with regard to loans at committee meetings shall be kept secret, and any member of the committee or officer of the registered society infringing this rule shall be liable to immediate expulsion or dismissal. Purposes for loans."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A34","no":34,"noLabel":{"en":"Section 34."},"text":{"en":"(1) No loan shall be granted except for a purpose to be approved in each by the\n\n(2) All loans granted shall be applied, by the borrowing members, to such purpose as the committee has approved. Misapplication of loans."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A35","no":35,"noLabel":{"en":"Section 35."},"text":{"en":"Where the committee is satisfied that a member of the registered society who has obtained a loan has applied the proceeds thereof to a purpose other than the purpose which is stated in the application under rule 32, the committee may, by notice in writing to the debtor, demand payment of the loan before the agreed date of payment. Documents to be completed before payment of loans."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A36","no":36,"noLabel":{"en":"Section 36."},"text":{"en":"When a loan is sanctioned by the committee and before the amount is paid, the borrower and his sureties shall execute an instrument in writing setting out the terms of repayment of the loan and such other terms and conditions as the committee may consider necessary: Provided that the Registrar may direct in respect of all registered societies or any specified registered societies the form of instrument to be signed by a borrower and his Security for loans."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A37","no":37,"noLabel":{"en":"Section 37."},"text":{"en":"(1) Loans, when approved by the committee, shall be granted to members who are able to obtain two sureties approved by the committee or who can give other security to the satisfaction of the committee.\n\n(2) Save with the sanction of the Registrar or as otherwise provided in the Act or in the rules, a registered society shall not lend money on the security of moveable\n\n(3) The shares of the registered society may not be hypothecated to that society by its members as security for a loan. Extension of loans."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A38","no":38,"noLabel":{"en":"Section 38."},"text":{"en":"If by reason of sickness or some other cause, a member finds that he will be unable to discharge his obligations to the registered society and notifies the secretary in writing before a loan is due, the committee may, with the consent of the sureties, if any, extend the time fixed for payment on such conditions as it thinks fit. Restrictions on loans to defaulters."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A39","no":39,"noLabel":{"en":"Section 39."},"text":{"en":"Where a member is in default in the payment of a loan and does not satisfy the committee that such default is due to good cause, such member shall not be entitled to receive another loan from the registered society. Recovery of loans."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A40","no":40,"noLabel":{"en":"Section 40."},"text":{"en":"Where a loan or an instalment of a loan has not been paid on the date on which it became due, and no extension for the payment thereof has been given to the borrower by the committee under rule 38, the committee shall take steps for the recovery thereof by referring the matter to the Registrar as prescribed in section 48."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A41","no":41,"noLabel":{"en":"Section 41."},"text":{"en":"(1) The reserve fund of a registered society, created in pursuance of the provisions of section 33(1), may with the sanction of the Registrar —\n\n(a) be utilised in the business of the registered society; or\n\n(b) be applied to meet occasional deficiencies incurred by the registered\n\n(2) In sanctioning the utilisation or application of the reserve fund under sub-rule (1), the Registrar may impose such terms and conditions as he may deem fit."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A42","no":42,"noLabel":{"en":"Section 42."},"text":{"en":"The committee may, with the approval of the Registrar, cause bad debts to be written off the books of the registered society in such manner and at such times as the Registrar may deem fit. Transfer of shares."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A43","no":43,"noLabel":{"en":"Section 43."},"text":{"en":"(1) Any share may be transferred with the approval of the committee to any other member at the option of the transferor, but if it is desired to transfer a share to a person who is not a member, such person must first be approved as a member by the committee, or the general meeting according to the by-laws relating to the admission of members before the transfer can be registered; and if the by-laws require a member to hold more than one share, the transferee must acquire the number so required to be held before the transfer can be registered.\n\n(2) No transfer of share shall be valid and effective unless and until such transfer has been registered by the secretary on the direction of the committee.\n\n(3) No transfer of a share shall be registered if made by a member indebted to the registered society without special order of the committee, and until the transfer of a share is registered, no right shall be acquired against the registered society by the transferee, nor shall any claim of the registered society upon the transferor be affected Sale of shares of members in default."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A44","no":44,"noLabel":{"en":"Section 44."},"text":{"en":"The committee may in default of payment by any member indebted to the registered society to an amount not less than three-fourths of the sum paid up for the time being on any transferable share held by him, sell, transfer and register in the books of the registered society such share to any person entitled to hold the same under the rules or by-laws for the best price obtainable therefor, and apply the proceeds in or towards the discharge of the debt so due and of any expense incurred in or about the same, paying over the balance (if any) to the member, without being responsible for loss occasioned thereby, and the defaulting member shall cease to have any further claim in respect of such share. Dispute proceedings same as before court of law."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A45","no":45,"noLabel":{"en":"Section 45."},"text":{"en":"(1) Reference of a dispute to the Registrar under section 48(1) may be made by the committee, or by the society by resolution in a general meeting, or by any party to the dispute or, if the dispute concerns a sum due from a member of the committee to the society, by any member of the society.\n\n(2) Where, in pursuance of the provisions of section 48(2)(b), the Registrar decides to refer a dispute to arbitration, he may either —\n\n(a) refer it to a single arbitrator appointed by himself; or\n\n(b) refer it to three arbitrators of whom one shall be nominated by each of the parties to the dispute and the third shall be nominated by the Registrar, who shall appoint the chairman. If any party to a dispute fails to nominate an arbitrator within 15 days, the Registrar may himself make the nomination.\n\n(3) The proceedings before the arbitrator or arbitrators shall, as nearly as possible, be conducted in the same way as proceedings before a court of law.\n\n(4) The Registrar or the arbitrator or arbitrators shall have power to —\n\n(a) administer oaths;\n\n(b) require the attendance of all parties concerned and witnesses and to require the production of all books and documents relating to the matter of the dispute, by a summons delivered orally or sent by hand or by registered post to the party’s last known address or served by the nearest court having jurisdiction in the area in which the society operates, and shall further have power to order the expenses of determining the dispute to be paid either out of the funds of the society or by such party or parties to the dispute as he may think fit.\n\n(5) The arbitrator appointed by the Registrar, or the arbitrators to whom the Registrar has referred a dispute, shall record a brief note of the evidence of the parties and witnesses who attend, and upon the evidence so recorded, and after consideration of any documentary evidence produced by either side, a decision or award, as the case may be, shall be given in accordance with justice, equity and good conscience and shall be reduced in writing. In the absence of any party duly summoned to attend, the dispute may be decided against him in default. In cases where three arbitrators are appointed, the opinion of the majority shall prevail.\n\n(6) Any person duly summoned by the Registrar or arbitrator or arbitrators by summons served by a court to appear before him or them, or to produce any document and falling to do so, may be proceeded against in accordance with the provisions of the\n\n(7) In any proceedings held under section 48, no party shall be represented by any legal practitioner except with the permission of the Registrar or the arbitrator or arbitrators, as the case may be. Statements and returns."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A46","no":46,"noLabel":{"en":"Section 46."},"text":{"en":"Every society shall furnish the Registrar with such information and with such statements and returns as may he called for by him. Copies of book entries."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A47","no":47,"noLabel":{"en":"Section 47."},"text":{"en":"For the purposes of section 20, a copy of an entry in a book of a registered society may be certified by a declaration dated and subscribed by the chairman and the secretary of the society that it is a true copy of such entry, that such entry is contained in one of the ordinary books of the society and was made in the usual and ordinary course of business and that such book is still in the custody of the society."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A48","no":48,"noLabel":{"en":"Section 48."},"text":{"en":"Except as expressly provided in the Act, no appeal shall lie against any order of the Registrar passed in any matter dealt with in the Act or in the rules framed under the Act. Irregular resolutions of societies to be rescinded."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A49","no":49,"noLabel":{"en":"Section 49."},"text":{"en":"The Registrar may rescind any resolution or action of an officer of a committee of a registered society or of a registered society which is, in his opinion, outside the objects and scope of the society as defined in the by-laws of the society, and may order the record of such resolution or act to be deleted from the records of the society. Fees."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A50","no":50,"noLabel":{"en":"Section 50."},"text":{"en":"The fees specified in the First Schedule hereto shall be payable for the matters which they relate: Provided that the Minister may direct that any fee paid in respect of an appeal to the Minister shall be refunded."}},{"id":"BN-CAP-84-R-1-2015-CO-OPERATIVE-SOCIETIES-RULES-A51","no":51,"noLabel":{"en":"Section 51."},"text":{"en":"(1) The forms in these Rules referred to are the forms contained in the Second\n\n(2) The forms shall be used in all cases to which they are applicable and slight deviations from these forms, or necessary alterations thereto not affecting the substance or calculated to mislead, shall not vitiate them.\n\n(3) The Registrar may direct that additional forms shall be used in any particular case or matter. (rule 50) FEES Fee to be paid on lodgement of an appeal under section 7, 10, 37 or 47 ..................... $25 (rules 6(1), 7(2) and 12(1)) Co-operative Societies Rules\n\nFORM OF APPLICATION FOR REGISTRATION OF A SOCIETY Under section 6 of the Co-operative Societies Act we, the under signed, apply that our society may be registered as a co-operative society with liabilitylimited under the style .................................................................................................................. Co-operative Society the address to be registered being ..............................limited ............................................................................................................................................ We also submit the by-laws adopted at our first general meeting at which the society was formed, duly signed, for registration. A copy of the minutes of the first general meeting is attached. — (continued)\n\nLIST OF APPLICANTS (Where members are individuals) No. Age Place of residence (To be signed by at least ten persons)\n\nLIST OF APPLICANTS (Where members are registered societies) No. of\n\nFORM B\n\nCERTIFICATE OF REGISTRATION Certificate of Registration No. .......................................................................... relating to application bearing number ........................................................................... and the year ................................ in the District of ................................................................................ I hereby certify that the Society under the name of ................................................. and its by-laws have this day been duly registered by me in the Register of Co-operative Societies in pursuance of the provisions of the Co-operative Societies Act and the Co-operative Societies Rules. Given under my hand at Bandar Seri Begawan this .............................................. day of ................................. 20 ...... Registrar of Co-operative Societies, Brunei Darussalam — (continued) Name of Society .......................................................... Date ............................................................................. The Registrar of Co-operative Societies, Brunei Darussalam, Sir, Application for Amendment of By-laws Under section 10 of the Co-operative Societies Act and rule 12 of the we, the of the ............................................................................................................................................ apply that the amendment to the following by-laws may be registered."}}],"pack":"bn-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"R 1 2015 ED CO OPERATIVE SOCIETIES RULES","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-CAP-85-1984-DIPLOMATIC-PRIVILEGES-EXTENSION-ACT"] = {"id":"BN-CAP-85-1984-DIPLOMATIC-PRIVILEGES-EXTENSION-ACT","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":6,"structureMode":"SECTION","title":{"zh":"外交特权扩展法","en":"DIPLOMATIC PRIVILEGES EXTENSION ACT","orig":"DIPLOMATIC PRIVILEGES EXTENSION ACT","vi":"Luật Mở rộng đặc quyền ngoại giao","th":"พระราชบัญญัติการขยายเอกสิทธิ์ทางการทูต","id":"Undang-Undang Perluasan Hak Istimewa Diplomatik","ms":"Akta Peluasan Keistimewaan Diplomatik"},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《CAP-85-1984-ED-DIPLOMATIC-PRIVILEGES-EXTENSION-ACT.pdf》（8 页），本次切分 6 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"CAP-85-1984-ED-DIPLOMATIC-PRIVILEGES-EXTENSION-ACT.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-CAP-85-1984-DIPLOMATIC-PRIVILEGES-EXTENSION-ACT-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"Short title"},"text":{"en":"This Act may be cited as the Diplomatic Privileges Short title (Extension) Act. .•"}},{"id":"BN-CAP-85-1984-DIPLOMATIC-PRIVILEGES-EXTENSION-ACT-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"international organisations and their staffs"},"text":{"en":"(1) This section shall apply to any organisation de-Privileges, clared by an order of His Majesty the Sultan and Yang immunities and capaciDi-Pertuan in Council to be an organisation of which His ties of certain Majesty's Government and the government or governments international organisations of one or more foreign sovereign Powers are members. and their staffs\n\n(2) His Majesty in Council may by order -\n\n(a) provide that any organisation to which this section applies (hereinafter referred to as \"the organisation\") shall, to such extent as may be specified in the order, have the immunities and privileges set out in Part I of the Schedule to this Act, and shall also have the legal capacities of a body corporate;\n\n(b) confer upon such number of officers of the organisation as may be specified in the order, being the holders of such high offices in the organisation as may be specified in the order, and upon such persons employed on missions on behalf of the organisation as may be specified, and upon any person who is the representative of a member government on the governing body or any committee B. L. R. 0. 111984 of the organisation, to such extent as may be so specified, the immunities and privileges set out in Part II of the Schedule to this Act;\n\n(c) confer upon such other classes of officers and servants of the organisation as may be specified in the order, to such extent as may be so specified, the immunities and privileges set out in Part III of the Schedule to this Act; and Part IV of the Schedule to this Act shall have effect for the purpose of extending to the staffs of representatives of member governments and to the families of officers of the organisation any immunities and privileges conferred on the representatives or officers under paragraph (b) of this subsection, except in so far as the operation of the said Part IV is excluded by the order conferring the immunities and privileges.\n\n(3) Where immunities and privileges are conferred on any persons by an order made under the last foregoing subsection, the Minister )'.\n\n(a) shall compile a list of the persons entitled to immunities and privileges conferred under paragraph (b) of that subsection, and may compile a list of the persons entitled to immunities and privileges conferred under paragraph (c) of that subsection;\n\n(b) shall cause any list compiled under this subsection to be published in a public notification; and\n\n(c) whenever any person ceases or begins to be entitled to the immunities and privileges to which - any such list relates, shall amend the list and cause a notice of the amendment, or, if he thinks fit, an amended list, to be published as aforesaid. ( 4) Every list or notice published under the last foregoing subsection shall state the date from which the list or amendment takes or took effect; and the fact that any person is or was included or not included at any time among the persons entitled to the immunities and privileges in question may, if a list of those persons has been so published, be conclusively proved by producing the public notification containing the list, or, as the case may be, the last list taking effect before that time, together '\":'ith the public notification (if any) containing notices of the amendments taking effect before that time, and by showing that the name of that person is or was at that time included or not included in the said list. •"}},{"id":"BN-CAP-85-1984-DIPLOMATIC-PRIVILEGES-EXTENSION-ACT-A3","no":3,"noLabel":{"en":"Section 3."},"heading":{"en":"international conferences"},"text":{"en":"(1) Where a conference is held in Brunei and is Diplomatic attended by the representatives of the government or gov-immunities of representaernments of one or more foreign sovereign Powers, and it tives attendappears to the Minister that doubts may arise as to the ing international conferextent to which the representatives of such foreign Powers ences and members of their official staffs are entitled to diplomatic immunities, he may(a) compile a list of the persons aforesaid who are entitled to such immunities, and cause that list to be published in a public notification; and\n\n(b) whenever it appears to the Minister that any person ceases or begins to be entitled to such immunities, amend the list and cause a notice of amendment or, if he thinks fit, an amended list, to be published as aforesaid; and every representative of a foreign Power who is for the time being included in the list shall, for the purpose of any law and rule of law or custom relating to the immunities of an envoy of a foreign Power accredited to His Majesty, and of the retinue of such an envoy, be treated as if he were such an envoy, and such of the members of his official staff as are B.L.R.O. l!/984 for the time being included in the list shall be treated for the purpose aforesaid as if they were his retinue.\n\n(2) Every list or notice published under the last foregoing subsection in relation to any conference shall include a statement of the date from which the list or amendment - takes or took effect; and the fact that any person is or was included or not included at any time among the persons entitled to diplomatic immunities as representatives attending the conference or as members of the official staff of any such representative may, if a list of those persons has been so published, be conclusively proved by producing the public notification containing the list or, as the case may be, the last list taking effect before that time, together with the public notification (if any) containing notices of the amendments taking effect before that time, and by showing that the name of that person is or was at that time included or not included in the said list. Application 4. This Act shall, in its application to the United Nato United Na-tions, have effect subject to the following modifications - tions _.·\n\n(a) any reference to the governing body or any committee of the organisation shall be construed as referring to the General Assembly or any council or other organ of the United Nations; and -\n\n(b) the powers conferred by subsection (2) of section 2 of this Act shall include power by order of His Majesty in Council to confer on the judges and registrars of the International Court of Justice and on suitors to that Court and their agents, counsel and advocates, such immunities, privileges and facilities as may be required to give effect to any resolution of, or convention approved by, the General Assembly of the United Nations."}},{"id":"BN-CAP-85-1984-DIPLOMATIC-PRIVILEGES-EXTENSION-ACT-A4","no":4,"noLabel":{"en":"Section 4."},"chapter":{"en":"PART I"},"heading":{"en":"Application to United Nations"},"text":{"en":"Exemption from taxes on the importation of goods, directly imported by the organisation for its official use in Brunei or for exportation, or on the importation of any publications of the organisation directly imported by it, such exemption to be subject to compliance with such conditions as the Controller of Customs may prescribe for the protection of the Revenue."}},{"id":"BN-CAP-85-1984-DIPLOMATIC-PRIVILEGES-EXTENSION-ACT-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"Nothing in the foregoing provisions of this Act shall Reciprocal be construed as precluding His Majesty in Council from treatment declining to accord immunities or privileges to, or from withdrawing immunities or privileges from, nationals or representatives of any Power on the ground that that Power is failing to accord corresponding immunities or privileges to -Brunei nationals or representatives.\n\nSCHEDULE (Section 2 (2)) Immunities and Privileges of the Organisation"}},{"id":"BN-CAP-85-1984-DIPLOMATIC-PRIVILEGES-EXTENSION-ACT-A6","no":6,"noLabel":{"en":"Section 6."},"chapter":{"en":"PART I"},"text":{"en":"The right to avail itself, for telegraphic communications sent by it and containing only matter intended for publication by the press or for broadcasting (including communications addressed to, or despatched from, places outside Brunei), of any reduced rates applicable for the corresponding service in the case of press telegrams. B.L.R.O. J/1984 Immunities and Privileges of High Officers, Persons on Missions and Government Representatives"}}],"pack":"bn-p24","summary":{"en":"An Act to make provision as to the immunities, privileges x of 1949 ff"},"titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"DIPLOMATIC PRIVILEGES EXTENSION ACT","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-CAP-86-GENEVA-AND-RED-CROSS-ACT"] = {"id":"BN-CAP-86-GENEVA-AND-RED-CROSS-ACT","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":2,"structureMode":"SECTION","title":{"zh":"日内瓦与红十字法","en":"GENEVA AND RED CROSS ACT","orig":"GENEVA AND RED CROSS ACT","vi":"Luật Geneva và Chữ thập đỏ","th":"พระราชบัญญัติเจนีวาและกาชาด","id":"Undang-Undang Jenewa dan Palang Merah","ms":"Akta Geneva dan Palang Merah"},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《CAP-86-GENEVA-AND-RED-CROSS-ACT.pdf》（4 页），本次切分 2 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"CAP-86-GENEVA-AND-RED-CROSS-ACT.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-CAP-86-GENEVA-AND-RED-CROSS-ACT-A1","no":1,"noLabel":{"en":"Section 1."},"heading":{"en":"Short title"},"text":{"en":"This Act may be cited as the Geneva and Red Cross Short title Act."}},{"id":"BN-CAP-86-GENEVA-AND-RED-CROSS-ACT-A2","no":2,"noLabel":{"en":"Section 2."},"heading":{"en":"designs"},"text":{"en":"(1) It shall not be lawful for any person without the Prohibition authority of His Majesty the Sultan and Yang Di-Pertuan to of use of emblem and use for the purpose of his trade or business or for any other certain words purpose whatsoever -,.. and designs\n\n(a) the heraldic emblen1 of the red cross on a white ground formed by reversing the Federal colours of Switzerland, or the words \"Red Cross\" or \"Geneva Cross\"; or\n\n(b) any design being a colourable imitation of the said emblem or any words so nearly resembling the words \"Red Cross\" or \"Geneva Cross\" as to be capable of being understood as referring to the said emblem; or\n\n(c) any design consisting of a white or silver cross on a red ground, none of the limbs of which extends to the margin of the ground, being the cross comprised in the Arms of the Swiss Confederation; or\n\n(d) any design being a colourable imitation of the design mentioned in the last foregoing paragraph.\n\n(2) If any person contravenes the provisions of this section, he shall, subject as hereafter provided, be guilty of B.L.R.O.J/1984 4 CAP. 86 Geneva and Red Cross an offence: Penalty, a fine of $1,000 and any goods upon or in connection with which the emblem, design or words were used forfeited.\n\n(3) Nothing in this section shall apply to a trade mark which before the 23rd day of December, 1931, was registered in the United Kingdon1 or lawfully used in Brunei - and which consists of or contains any such design as is mentioned in paragraph (c) or paragraph (d) of subsection (1) of this section; and where a person is charged with using such a design for any purpose and it is proved that he used it otherwise than as or as part of a trade mark registered or lawfully used as aforesaid it shall be a defence for hin1 to prove -\n\n(a) that before the said 23rd day of Decen1ber 1931 he lawfully used that design for that purpose in the United Kingdom or in Brunei; or\n\n(b) in a case where he is charged with using the design upon goods, that the design has been applied to the goods before he acquired them by some other person who had manufactured or dealt with the goods in the course of trade, and that that other person lawfully used the design in the United Kingdom br in Brunei upon similar goods before the said 23rd day of December 1931.\n\n(4) When an offence under this Act committed by a body corporate is proved to have been committed with the consent or connivance of ·any director, manager, secretary or other officer of the body corporate, he as well as the body corporate shall be deemed to be guilty of an offence and shall be liable to be proceeded against and punished accordingly.\n\n(5) Proceedings under this Act shall not be instituted - without the consent of the Attorney General."}}],"pack":"bn-p24","summary":{"en":"An Act to control the use of the heraldic emblems of the Red 6 of 1938"},"titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"GENEVA AND RED CROSS ACT","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT"] = {"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":22,"structureMode":"SECTION","title":{"zh":"调查委员会法","en":"COMMISSIONS OF INQUIRY ACT","orig":"COMMISSIONS OF INQUIRY ACT","vi":"Luật Ủy ban điều tra","th":"พระราชบัญญัติคณะกรรมการสอบสวน","id":"Undang-Undang Komisi Penyelidikan","ms":"Akta Suruhanjaya Siasatan"},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《CAP-9-2014-ED-COMMISSIONS-OF-INQUIRY-ACT.pdf》（12 页），本次切分 22 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"CAP-9-2014-ED-COMMISSIONS-OF-INQUIRY-ACT.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act may be cited as the Commissions of Inquiry Act. Issue of Commission."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"(1) His Majesty the Sultan and Yang Di-Pertuan in Council may, where it appears to him to be expedient to do so, issue a Commission appointing one or more Commissioners and authorising such Commissioners\n\n(a) the conduct of any officer;\n\n(b) the conduct or management of any department of the public service of Brunei Darussalam;\n\n(c) the conduct or management of any public institution which is not solely maintained by Brunei Darussalam funds;\n\n(d) any other matter in which an enquiry would, in the opinion of His Majesty the Sultan and Yang Di-Pertuan in Council, be for the Provided that where any officer into whose conduct it is proposed to enquire, is Seconded Officer, such Commission shall only be issued with the concurrence of the competent authority of the territory from which such officers was appointed.\n\n(2) In this section, unless the context otherwise requires — “Seconded Officer” means an officer on the permanent establishment of the government of another territory who by agreement is seconded to the service of Brunei Darussalam. Terms of Commission."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"(1) A Commission issued under section 2 shall specify the subject of the enquiry and may, in the discretion of His Majesty the Sultan and Yang Di-Pertuan in Council —\n\n(a) if there is more than one Commissioner, direct —\n\n(i) which Commissioner shall be Chairman;\n\n(ii) the number of Commissioners which shall constitute a ;\n\n(b) direct where and when the enquiry shall be held and the report thereof rendered;\n\n(c) direct whether the enquiry or any part thereof shall or shall not be held in public;\n\n(d) generally prescribe how such Commission shall be executed.\n\n(2) When the Commission specifies the number of Commissioners which shall constitute a quorum, the number of Commissioners so specified may, in the absence of the other Commissioner or Commissioners, exercise all or any of the powers conferred upon the Commissioners by this Act. Power to add or substitute Commissioners."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"(1) His Majesty the Sultan and Yang Di-Pertuan in Council may add to the persons named in any such Commission, and in any case any person appointed or added under this Act dies, resigns, desires to be discharged, refuses or becomes incapable of acting, His Majesty the Sultan and Yang Di-Pertuan in Council may appoint a new Commissioner in his place, and all the powers and duties by this Act conferred and imposed on a Commissioner shall be exercised and performed by the Commissioner so added or\n\n(2) When a new Commissioner has been appointed under the provisions of subsection (1), it shall not be necessary for any evidence which may have been taken before the Commission prior to such appointment to be retaken. Enlargement of time."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"His Majesty the Sultan and Yang Di-Pertuan in Council may, by endorsement under his hand on a Commission, enlarge the time for the execution of the Commission, whether the time for the execution has expired"}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"No Commission issued under this Act shall lapse by reason of, or be otherwise affected by, the demise of His Majesty the Sultan and Yang Appointment of secretary."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"His Majesty the Sultan and Yang Di-Pertuan in Council may appoint a secretary to attend the sittings of the Commission, to record their proceedings, to keep their papers, summon and record the evidence of witnesses, and generally to perform such duties connected with the enquiry as the Commissioner shall order, subject to the directions, if any, of His Majesty the Sultan and Yang Di-Pertuan in Council. Powers of Commissioners."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The Commissioners shall have the following powers —\n\n(a) to procure and receive all such evidence, whether written or oral and to examine all such persons as witnesses, as the Commissioners may think it necessary or desirable to procure or\n\n(b) to require the evidence (whether written or oral) of any witness to be made on oath or affirmation (such oath or affirmation to be that which could be required of the witness if he were giving evidence in the High Court) or by statutory declaration;\n\n(c) to summon any person in Brunei Darussalam to attend any meeting of the Commissioners to give evidence or produce any document or other thing in his possession and to examine him as a witness or require him to produce any document or other thing in his\n\n(d) to issue a warrant of arrest to compel the attendance of any person who, after having been summoned to attend, fails to do so, and does not excuse such failure to the satisfaction of the Commissioners, and to order him to pay all costs which may have been occasioned in compelling his attendance or by reason of his refusal to obey the summons, and also to fine such person a sum not exceeding $500;\n\n(e) to fine a sum not exceeding $500 any person who, being required by the Commissioners to give evidence on oath or affirmation or to produce a document or other thing, refuses to do so and does not excuse such refusal to the satisfaction of the Commissioners;\n\n(f) notwithstanding the provisions of any written law relating to evidence, to admit any evidence, whether written or oral, which might be inadmissible in civil or criminal proceedings;\n\n(g) subject to any direction contained in the Commission —\n\n(i) to admit or exclude the public from the enquiry or any\n\n(ii) to admit or exclude the press from the enquiry or any part\n\n(h) to award any person who has attended any meeting of the Commissioners, including any interpreter appointed under section 9, such sums as in the opinion of the Commissioners may have been reasonably incurred by him by reason of such attendance."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"(1) The Commissioners shall have the power to appoint any person, whether in the service of the Government or not, to act as interpreter in any matter brought before them and to translate any books, papers or writings produced to them.\n\n(2) Any interpreter appointed under this section shall make and subscribe before the Commissioners the following affirmation: “I, .................................................................................................. do solemnly declare and affirm that I will faithfully perform the duties of interpreter and will truly interpret the questions put and the answers given by witnesses and also statements made by the Commissioners and will truly translate or explain and transcribe all documents entrusted to me for such purpose to the best of my ability, and that I will not, except as authorised by the Commissioners, directly or indirectly, reveal the contents of such documents as may be entrusted to me, nor the evidence given by witnesses which may have been interpreted by me.”."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"Any sums awarded by the Commissioners under section 8(h) shall be paid out of the public funds of Brunei Darussalam. Use of evidence in civil and criminal proceedings."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"No evidence taken under this Act shall be admissible in any civil or criminal proceedings whatsoever against the person who gave such evidence, except when such person is charged with giving or fabricating false Penalty for threats etc. to witnesses."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"(1) Any person who hinders or attempts to hinder any person from giving evidence before the Commissioners or by threats, deters or attempts to deter any person from giving such evidence, is guilty of an offence and liable on conviction to imprisonment for 2 years.\n\n(2) Any person who threatens, insults or injures any person for having given evidence, or on account of the evidence which he has given before the Commissioners, is guilty of an offence and liable on conviction to imprisonment for 2 years. Penalty for contempt."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Any person who commits an act of contempt as defined in section 14 against the Commissioners or any of them is guilty of an offence and liable on conviction to a fine of $1,000 and imprisonment for 6 months. Definition of act of contempt."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"The following shall be deemed to be an act of contempt within the meaning of section 13 —\n\n(a) any act of disrespect, or any insult or threat, offered to the Commissioners or any of them while sitting in Commission;\n\n(b) any act of disrespect, or any insult or threat, offered to a Commissioner at any other time and place on account of his proceedings in his capacity as a Commissioner;\n\n(c) any act of refusal to comply with the requirement of the Commissioners to give evidence on oath or affirmation or to produce a document or any other thing. Manner of dealing with contempt."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"(1) Where an act of contempt is committed in the presence of the Commissioners sitting in Commission, the Commissioners may, after hearing the offender in his defence, pass sentence upon him forthwith in accordance with section 13.\n\n(2) In any other case, the Commissioners may summon the offender to appear before them at a time and place to be specified in such summons, to show cause why he should not be judged to have committed an act of contempt, and be dealt with in accordance with the provisions of section 13.\n\n(3) If any person who has been summoned in accordance with the provisions of subsection (2) fails to attend at the time and place specified in the summons, the Commissioners may issue a warrant to compel the attendance of such person. Public Prosecutor to aid Commissioners."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"(1) The Commissioners may require the Public Prosecutor to cause any matter relevant to the enquiry to be investigated.\n\n(2) Any person appointed by the Public Prosecutor to investigate any such matter shall, for the purposes of such investigations, have all the powers in relation to police investigations given to police officers under the provisions of Chapter XIII of the Criminal Procedure Code (Chapter 7) and may, when authorised in writing by the Public Prosecutor, search any premises and take possession of any articles or documents as specified in such authority. Preservation of order by police."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"His Majesty the Sultan and Yang Di-Pertuan may direct the Commissioner of Police to detail police officers to attend upon any such Commissioners, to preserve order during the proceedings and to serve summonses on witnesses and to perform such ministerial duties as such Commissioners shall direct. Right to representation by counsel."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"(1) Any person whose conduct is the subject of enquiry under this Act, or who is in any way implicated or concerned in the matter under enquiry, shall be entitled to be represented by an advocate at the whole of the enquiry; and any other person who may consider it desirable that he should be so represented may, by leave of the Commissioner or Commissioners, be represented in the manner aforesaid.\n\n(2) The Attorney General, or any person authorised by him in writing, shall be entitled at any time to appear before and address the Commissioners on any matter which to the Attorney General appears to be relevant to the proceedings under Penal Code (Chapter 22)."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A19","no":19,"noLabel":{"en":"Section 19."},"heading":{"en":"Commissioners to be public servants and enquiries to be judicial"},"text":{"en":"Every Commissioner appointed under this Act shall, so long as he is acting as such Commissioner, be deemed to be a public servant within the meaning and for the purposes of the Penal Code (Chapter 22), and every enquiry under this Act shall be deemed to be a judicial proceeding within the meaning of such Code. Commissioners to have powers of Magistrates."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"For the purposes of recovering any costs awarded, enforcing the payment of any fine ordered or imposed or giving effect to any warrant of arrest or order of imprisonment, the Commissioners or any of them shall have the powers of a Magistrate. Protection of Commissioners and witnesses."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"(1) No Commissioner shall be liable to any suit or other civil proceeding for any act or thing done by him as such Commissioner.\n\n(2) All evidence given for the purposes of any enquiry under this Act shall be absolutely privileged so that the witness giving such evidence shall not be liable to any suit or other civil proceeding in respect of such evidence. Procedure and forms."}},{"id":"BN-CAP-9-2014-COMMISSIONS-OF-INQUIRY-ACT-A22","no":22,"noLabel":{"en":"Section 22."},"heading":{"en":"____________________________"},"text":{"en":"Subject to the provisions of this Act, the procedure to be followed by the Commissioners and the form of any order, summons, warrant or other documents made or issued for the purposes of this Act shall be in the discretion of the Commissioners."}}],"pack":"bn-p24","summary":{"en":"An Act to make provision for the holding of Commissions of Inquiry"},"titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"COMMISSIONS OF INQUIRY ACT","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT"] = {"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":24,"structureMode":"SECTION","title":{"zh":"机动车保险第三者风险法","en":"MOTOR VEHICLES INSURANCE THIRD PARTY RISKS ACT","orig":"MOTOR VEHICLES INSURANCE THIRD PARTY RISKS ACT","vi":"Luật Bảo hiểm trách nhiệm bên thứ ba của xe cơ giới","th":"พระราชบัญญัติการประกันภัยรถยนต์ความรับผิดต่อบุคคลภายนอก","id":"Undang-Undang Asuransi Kendaraan Bermotor Tanggung Jawab Pihak Ketiga","ms":"Akta Insurans Kenderaan Bermotor Risiko Pihak Ketiga"},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《CAP-90-2014-ED-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT.pdf》（24 页），本次切分 24 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"CAP-90-2014-ED-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act may be cited as the Motor Vehicles Insurance (Third Party Risks) Act."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In this Act, unless the context otherwise requires — “Authority” means the Autoriti Monetari Brunei Darussalam established by the Autoriti Monetari Brunei Darussalam Order, “Commissioner of Police” has the same meaning as in the Royal Brunei Police Force Act (Chapter 50); “company” includes any company incorporated within or outside Brunei Darussalam and any firm or partnership; “motor vehicle” means a mechanically propelled vehicle intended or adapted for use on roads, but does not include an invalid “owner”, in relation to a vehicle which is subject to a hiring agreement or hire purchase agreement, means the persons in possession of the vehicle under the agreement; “police constable” means any member of the Police Force constituted under the Royal Brunei Police Force Act (Chapter 50), but does not include a special police officer or an additional police “policy of insurance” includes a covering note; “road” means any highway and any other road to which the public has access, and includes bridges over which a road passes. Users of motor vehicles to be insured against third party risks."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"(1) Subject to the provisions of this Act, it shall not be lawful for any person to use on a road, or to cause or permit any other person to use on a road, a motor vehicle unless there is in force in relation to the user of the motor vehicle by that person or that other person, as the case may be, such a policy of insurance or such a security in respect of third party risks as complies with the requirements of this Act.\n\n(2) If a person acts in contravention of this section, he is guilty of an offence and liable on conviction to a fine of $10,000 and imprisonment for 12 months, and a person convicted of an offence under this section shall, unless the court for special reasons thinks fit to order otherwise and without prejudice to the power of the court to order a longer period of disqualification, be disqualified from holding or obtaining a driving licence under the Road Traffic Act (Chapter 68), for a period of 12 months from the date of the conviction.\n\n(3) For the purposes of the Road Traffic Act (Chapter 68) —\n\n(a) a person convicted under this section is deemed to be convicted of an offence in connection with the driving of a motor\n\n(b) a person disqualified by virtue of a conviction under this section or of an order made thereunder from holding or obtaining a driving licence is deemed to be disqualified by virtue of a conviction or order under that Act.\n\n(4) Notwithstanding any written law prescribing a time within which proceedings may be brought before a court, proceedings for an offence under this section may be brought —\n\n(a) within a period of 6 months from the date of the commission of the alleged offence; or\n\n(b) within a period which exceeds neither 3 months from the date on which it came to the knowledge of the prosecutor that the offence had been committed nor one year from the date of the commission of whichever period is the longer.\n\n(5) This section does not apply to —\n\n(a) a vehicle owned by the Government upon any occasion upon which such vehicle is being used by a person authorised by the Government to use the vehicle on such occasion;\n\n(b) a vehicle owned by a person who has deposited and keeps deposited with the State Financial Officer such sum as the Authority may direct, at any time when the vehicle is being driven by the owner or by a servant of the owner in the course of his employment or is otherwise subject to the control of the owner; or\n\n(c) any vehicle at any time when it is being driven for police purposes by or under the direction of a police constable or by a person employed by the Commissioner of Police. Requirements in respect of policies."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"(1) In order to comply with the requirements of this Act, a policy of insurance must be a policy which —\n\n(a) is issued by an insurer approved by the Authority but, if the insurer does not reside within Brunei Darussalam no such approval shall be given unless the Authority is satisfied that the insurer has complied with the provisions of section 18(1) and (2);\n\n(b) insures such person, persons or classes of persons as may be specified in the policy in respect of any liability which may be incurred by him or them in respect of the death of, or bodily injury to, any person caused by or arising out of the use of the motor vehicle on a road: Provided that such a policy shall not be required to cover —\n\n(i) liability in respect of the death arising out of and in the course of his employment of a person in the employment of a person insured by the policy or of bodily injury sustained by such a person arising out of and in the course of his employment;\n\n(ii) except in the case of a motor vehicle in which passengers are carried for hire or reward or by reason of or in pursuance of a contract of employment, liability in respect of the death of or bodily injury to persons being carried in or upon, or entering or getting on to, or alighting from, the motor vehicle at the time of the occurrence of the event out of which the claims arise; or\n\n(iii) any contractual liability.\n\n(2) Where any payment is made (whether or not with an admission of\n\n(a) an approved insurer under or in consequence of a policy issued under this Act;\n\n(b) the owner of a motor vehicle in relation to the user of which a security under section 5 is in force; or\n\n(c) the owner of a motor vehicle who has made a deposit under in respect of the death of or bodily injury to any person arising out of the use of a motor vehicle on a road, and the person who has so died or been bodily injured has, to the knowledge of the approved insurer or such owners as the case may be, received treatment at a hospital, whether as an in-patient or as an out-patient, in respect of the injury so arising, there shall also be paid by the approved insurer or such owner to such hospital the expenses reasonably incurred by the hospital in affording such treatment, after deducting from such expenses any moneys actually received by the hospital in payment of a specific charge for such treatment: Provided that the amount to be paid by the approved insurer or such owner shall not exceed $1,500 for each person so treated as an in-patient or $150 for each person so treated as an out-patient. For the purposes of this subsection — “hospital” means an institution (not being an institution carried on for profit) which provides medical or surgical treatment for “expenses reasonably incurred” means —\n\n(a) in relation to a person who receives treatment at a hospital as an in-patient, the amount chargeable to a member of the general public, in a ward of the class occupied by the person who received treatment, in accordance with the scale of fees normally charged by the hospital; and\n\n(b) in relation to a person who receives treatment at a hospital as an out-patient, reasonable expenses actually incurred.\n\n(3) Notwithstanding the provisions of any written law to the contrary, a person issuing a policy of insurance under this section shall be liable to indemnify the persons or classes of persons specified in the policy in respect of any liability which the policy purports to cover in the case of those persons or classes of persons.\n\n(4) A policy shall be of no effect for the purposes of this Act unless and until there is issued by the insurer to the person by whom the policy is effected a certificate (referred to in this Act as a certificate of insurance) in the prescribed form and containing such particulars of any conditions subject to which the policy is issued and of any other matters as may be prescribed, and different forms and different particulars may be prescribed in relation to different cases or circumstances. Requirements in respect of securities."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"(1) In order to comply with the requirements of this Act, a security must —\n\n(a) be given either by an insurer approved by the Authority or by some body of persons approved by the Authority which carries on the business of giving securities of a like kind but, if the insurer or such body of persons do not reside within Brunei Darussalam, no such approval shall be given unless the Authority is satisfied that the insurer or such body of persons has complied with the provisions of section 18(1) and (2); and\n\n(b) consist of an undertaking by the giver of the security to make good subject to any conditions specified therein and up to the amount in the case of an undertaking relating to the use of motor vehicles in which passengers are carried for hire or reward of not less than $225,000 and in any other case of not less than $45,000 and any failure by the owner of the vehicle or such other persons or classes of persons as may be specified in the security duly to discharge any such liability as is required to be covered by a policy of insurance under section 4 which may be incurred by him or them.\n\n(2) A security shall be of no effect for the purposes of this Act unless and until there is issued by the person giving the security to the person to whom it is given a certificate (referred to in this Act as a certificate of security) in the prescribed form and containing such particulars of any conditions subject to which the security is issued and of any other matters as may be prescribed, and different forms and different particulars may be prescribed in relation to different cases or circumstances. Certain conditions to policies or securities to be of no effect."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"Any condition in a policy or security issued or given for the purposes of this Act providing that no liability shall arise under the policy or security, or that any liability so arising shall cease in the event of some specified thing being done or omitted to be done after the happening of the event giving rise to a claim under the policy or security, shall be of no effect in connection with such claims as are mentioned in section 4(1)(b): Provided that nothing in this section shall be taken to render void any provision in a policy or security requiring the person insured or secured to repay to the insurer or the giver of the security any sums which the latter may have become liable to pay under the policy or security and which have been applied to the satisfaction of the claims of third parties. Avoidance of restrictions on scope of policies covering third party risks."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A7","no":7,"noLabel":{"en":"Section 7."},"heading":{"en":"Avoidance of restrictions on scope of policies covering third party"},"text":{"en":"Where a certificate of insurance has been issued under section 4(4) to the person by whom a policy has been effected, so much of the policy as purports to restrict the insurance of the persons insured thereby by reference to any of the following matters —\n\n(a) the age or physical or mental condition of persons driving the\n\n(b) the condition of the vehicle;\n\n(c) the number of persons that the vehicle carries;\n\n(d) the weight or physical characteristics of the goods that the\n\n(e) the times at which, or the areas within which, the vehicle is used;\n\n(f) the horse-power or value of the vehicle;\n\n(g) the carrying on the vehicle of any particular apparatus; or\n\n(h) the carrying on the vehicle of any particular means of identification other than any means of identification required to be carried by or under any written law relating to motor vehicles, shall as respects such liabilities as are required to be covered by a policy\n\n(b) be of no effect: Provided that nothing in this section shall require an insurer to pay any sum in respect of the liability of any person otherwise than in or towards the discharge of that liability, and any sum paid by an insurer in or towards the discharge of any liability of any person which is covered by the policy by virtue only of this section shall be recoverable by the insurer from that Applicants for motor vehicle furnish licences to evidence of insurance."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A8","no":8,"noLabel":{"en":"Section 8."},"heading":{"en":"Applicants for motor vehicle furnish licences to evidence of"},"text":{"en":"Every person, when applying for a driving licence under the Road Traffic Act (Chapter 68) to authorise him to drive a motor vehicle, shall furnish to the Licensing Officer to whom the application is being made such evidence as may be prescribed that either —\n\n(a) on the date when the licence comes into operation there will be in force the policy of insurance or the security required by this Act in relation to the use of the motor vehicle by the applicant or by other persons on his order or with his permission; or\n\n(b) the motor vehicle is a vehicle to which section 3 does not apply at any time when it is being driven by the owner thereof or by a servant of his in the course of his employment or is otherwise subject to the control of the owner. Duty of insurers to satisfy judgments against persons insured in respect of third party risks."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A9","no":9,"noLabel":{"en":"Section 9."},"heading":{"en":"Duty of insurers to satisfy judgments against persons insured in"},"text":{"en":"(1) If after a certificate of insurance has been issued under section 4(4) to the person by whom a policy has been effected, judgment in respect of any such liability as is required to be covered by a policy under\n\n(b) (being a liability covered by the terms of the policy) is obtained against any person insured by the policy, then, notwithstanding that the insurer may be entitled to avoid or cancel or may have avoided or cancelled the policy, the insurer shall subject to the provisions of this section pay to the persons entitled to the benefit of the judgment any sum payable thereunder in respect of the liability, including any amount payable in respect of costs and any sum payable in respect of interest on that sum by virtue of any written law relating to interest on judgments.\n\n(2) No sum shall be payable by an insurer under the foregoing\n\n(a) in respect of any judgment, unless before or within 7 days after the commencement of the proceedings in which the judgment was given the insurer had notice of the bringing of the proceedings;\n\n(b) in respect of any judgment so long as execution thereon is stayed pending an appeal; or\n\n(c) in connection with any liability if, before the happening of the event which was the cause of the death or bodily injury giving rise to the liability, the policy was cancelled by mutual consent or by virtue of any provision contained therein and either —\n\n(i) before the happening of the event, the certificate was surrendered to the insurer or the person to whom the certificate was issued made a statutory declaration stating that the certificate had been lost or destroyed;\n\n(ii) after the happening of the event but before the expiration of a period of 14 days from the taking effect of the cancellation of the policy, the certificate was surrendered to the insurer, or the person to whom the certificate was issued made such a statutory declaration as mentioned in sub-paragraph (i); or\n\n(iii) either before or after the happening of the event but within the said period of 14 days, the insurer has commenced proceedings under this Act in respect of the failure to surrender the certificate.\n\n(3) No sum shall be payable by an insurer under the foregoing provisions if in an action, commenced before or within 3 months after the commencement of the proceedings in which the judgment was given, he has obtained a declaration that, apart from any provision contained in the policy, he is entitled to avoid it on the ground that it was obtained by the nondisclosure of a material fact or by a representation of fact which was false in some material particular or, if he has avoided the policy on that ground, that he was entitled to do so apart from any provisions contained in it: Provided that an insurer who has obtained such a declaration as aforesaid in an action shall not thereby become entitled to the benefit of this subsection as respects any judgment obtained in proceedings commenced before the commencement of that action unless, before or within 7 days after the commencement of that action, he has given notice thereof to the person who is the plaintiff in that proceedings specifying the non-disclosure or false representation on which he proposes to rely, and any person to whom notice of such an action is so given shall be entitled if he thinks fit to be made a party thereto.\n\n(4) If the amount which an insurer becomes liable under this section to pay in respect of a liability of a person insured by a policy exceeds the amount for which he would apart from the provisions of this section be liable under the policy in respect of that liability, he shall be entitled to recover the excess from that person.\n\n(5) In this section — “material” means of such a nature as to influence the judgment of a prudent insurer in determining whether he will take the risk and, if so, at what premium and on what conditions; “liability covered by the terms of the policy” means a liability which is covered by the policy or which would be so covered but for the fact that the insurer is entitled to avoid or cancel or has avoided or cancelled the policy.\n\n(6) In this Act, references to a certificate of insurance in any provision, relating to the surrender or the loss or destruction of a certificate of insurance, shall in relation to policies under which more than one certificate is issued be construed as references to all the certificates and shall, where any copy has been issued of any certificate, be construed as including a reference to that copy. Rights of third parties against insurers."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"(1) Where under any policy issued for the purposes of this Act, a person (hereinafter called “the insured”) is insured against liabilities to third parties which he may incur, then —\n\n(a) in the event of the insured becoming bankrupt or making a composition or arrangement with his creditors; or\n\n(b) in the case of the insured being a company, in the event of a winding-up order being made or a resolution for a voluntary winding-up being passed with respect of the company, or of a receiver or manager of the company’s business or undertaking being duly appointed, or of possession being taken by or on behalf of the holders of any debentures secured by a floating charge of any property comprised in or subject to the charge, if, either before or after that event, any such liability is incurred by the insured, his rights against the insurer under the policy, in respect of the liability, shall, notwithstanding the provisions of any written law to the contrary, be transferred to and vest in the third party to whom the liability was so incurred.\n\n(2) Where an order is made under any law for the time being in force relating to bankruptcy for the administration in bankruptcy of the estate of a deceased debtor, then, if any debt provable in bankruptcy is owing by the deceased in respect of a liability against which he was insured under a policy issued for the purposes of this Act as being a liability to a third party, the deceased debtor’s rights against the insurer under the policy in respect of that liability shall, notwithstanding the provisions of any written law to the contrary, be transferred to and vest in the person to whom the debt is owing.\n\n(3) Any condition in a policy issued for the purposes of this Act, purporting directly or indirectly to avoid the policy or to alter the rights of the party thereunder upon the happening to the insured of any of the events specified in subsection (1)(a) or (b) or upon the making of an order under any law for the time being in force relating to bankruptcy for the administration in bankruptcy of his estate, shall be of no effect.\n\n(4) Upon a transfer under subsection (1) or (2), the insurer shall, subject to the provisions of section 12, be under the same liability to the third party as he would have been under to the insured but if the liability of the insurer to the insured —\n\n(a) exceeds the liability of the insured to the third party, nothing in this Act shall affect the rights of the insured against the insurer in respect of the excess;\n\n(b) is less than the liability of the insured to the third party, nothing in this Act shall affect the rights of the third party against the insured in respect of the balance.\n\n(5) For the purposes of this section and of sections 11 and 12, “liabilities to third parties”, in relation to a person insured under any policy of insurance, does not include any liability of that person in the capacity of insurer under some other policy of insurance.\n\n(6) This section and sections 11 and 12 do not apply —\n\n(a) where a company is wound up voluntarily merely for the purposes of reconstruction or of amalgamation with another company; or\n\n(b) to any case in which, under any written law making provision for the payment of compensation to workmen for injuries suffered in the course of their employment, the rights of an employer against an insurer in respect of liability for such compensation are transferred to and vested in the third party. Duty to give necessary information to third parties."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"(1) Any person, against whom a claim is made in respect of any such liability as is required to be covered by a policy under section 4(1)(b), shall, on demand by or on behalf of the person making the claim, state whether or not he was insured in respect of that liability by any policy having effect for the purposes of this Act or would have been so insured if the insurer had not avoided or cancelled the policy, and if he was or would have been so insured, give such particulars with respect to that policy as were specified in the certificate of insurance delivered in respect thereof under section 4(4).\n\n(2) In the event of —\n\n(a) any person becoming bankrupt or making a composition or arrangement with his creditors;\n\n(b) an order being made under any law for the time being in force relating to bankruptcy for the administration in bankruptcy in respect of the estate of any person; or\n\n(c) a winding-up order being made or a resolution for a voluntary winding-up being passed with respect to any company or of a receiver or manager of the company’s business or undertaking being duly appointed or of possession being taken by or on behalf of the holders of any debentures secured by a floating charge of any property comprised in or subject to the charge, it shall be the duty of the bankrupt debtor, personal representative of the deceased debtor or company and, as the case may be, of the officer having jurisdiction under any law for the time being in force relating to bankruptcy, trustee, liquidator, receiver or manager or person in possession of the property to give, at the request of any person claiming that the bankrupt debtor, deceased debtor or company is under a liability to him, such information as may reasonably be required by him for the purpose of ascertaining whether any rights have been transferred to and vested in him by this Act and for the purpose of enforcing such rights if any, and any contract of insurance, in so far as it purports whether directly or indirectly to avoid the contract or to alter the rights of the parties thereunder upon the giving of any such information in the events aforesaid or otherwise to prohibit or prevent the giving thereof in the said events, shall be of no effect.\n\n(3) If the information given to any person, in pursuance of subsection (2), discloses reasonable ground for supposing that there have or may have been transferred to him under this Act, rights against any particular insurer, that insurer shall be subject to the same duty as is imposed by subsection (2) on the person therein mentioned.\n\n(4) The duty to give information imposed by this section shall include a duty to allow all contracts of insurance receipts for premiums and other relevant documents in the possession or power of the person on whom the duty is so imposed to be inspected and copies thereof to be taken.\n\n(5) If, without reasonable excuse, any person fails to comply with the provisions of this section or wilfully makes any false or misleading statement in reply to any such demand, he is guilty of an offence. Settlement between insurers and insured persons."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"Where a person who is insured under a policy issued for the purposes of this Act has become bankrupt, or where in the case of such insured person being a company, a winding-up order has been made or a resolution for a voluntary winding-up has been passed with respect to the company, no agreement made between the insurer and the insured after liability has been incurred to a third party and after the commencement of the bankruptcy or winding-up, as the case may be, nor any waiver assignment or other disposition made by or payment made to the insured after the commencement, shall be effective to defeat or affect the rights transferred to the third party under this Act, but those rights shall be the same as if no such agreement, waiver, assignment, disposition or payment had been made."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A13","no":13,"noLabel":{"en":"Section 13."},"heading":{"en":"Bankruptcy, insured persons not to affect certain claims by third"},"text":{"en":"Where a certificate of insurance has been issued under section 4(4) to the person by whom a policy has been effected, the happening in relation to any person insured by the policy of any such event as is mentioned in section 10(1) or (2) shall, notwithstanding anything in this Act, not affect any such liability of that person as is required to be covered by a policy under\n\n(b), but nothing in this section shall affect any rights against the insurer conferred under sections 10, 11 and 12 on the person to whom the liability was incurred. Further rights of third parties against insurers."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"(1) No settlement by an insurer, in respect of any claim which might be made by a third party in respect of any such liability as is required to be covered by a policy under section 4(1)(b), shall be valid unless such third party is a party to such settlement.\n\n(2) A policy issued under this Act shall remain in force and available for third parties notwithstanding the death of any person insured under\n\n(b) as if the insured person was still alive. Duty to surrender certificate on cancellation of policy."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"Where a certificate of insurance has been issued under section 4(4) to the person by whom a policy has been effected and the policy is cancelled by mutual consent or by virtue of any provision in the policy, the person to whom the certificate was issued shall, within 7 days from the taking effect of the cancellation, surrender the certificate to the insurer or, if it has been lost or destroyed, make a statutory declaration to that effect, and if he fails to do so he is guilty of an offence. Requirements as to production of certificate of insurance or security."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A16","no":16,"noLabel":{"en":"Section 16."},"heading":{"en":"Requirements as to production of certificate of insurance or"},"text":{"en":"(1) Any person driving a motor vehicle on a road shall, on being so required by a police constable, give his name and address of the owner of the motor vehicle and produce his certificate, and if he fails so to do he is guilty Provided that if the driver of a motor vehicle within 5 days after the date on which the production of his certificate was so required, produces the certificate in person at such police station as may have been specified by the driver at the time its production was required, he shall not be convicted of an offence under this subsection by reason only of failure to produce his certificate to the police officer.\n\n(2) If, in any case where owing to the presence of a motor vehicle on a road, an accident occurs involving personal injury to another person, the driver of the vehicle does not at the time produce his certificate to a police constable or to some other person who having reasonable grounds for so doing has required its production, the driver shall, as soon as possible and in any case within 24 hours of the occurrence of the accident, report the accident at a police station and thereupon produce his certificate, and if he fails to do so he is guilty of an offence: Provided that a person shall not be convicted of an offence under this subsection by reason only of failure to produce his certificate if, within 5 days after the occurrence of the accident, he produces the certificate in person at such police station as may be specified by him at the time the accident was reported.\n\n(3) It shall be the duty of the owner of a motor vehicle to give such information as he may be required by or on behalf of the Commissioner of Police to give for the purpose of determining whether the motor vehicle was or was not being driven in contravention of section 3 on any occasion when the driver was required under this section to produce his certificate, and if the owner fails to do so he is guilty of an offence.\n\n(4) In this section, “produce his certificate” means produce for examination the relevant certificate of insurance or certificate of security or such other evidence that the motor vehicle is not or was not being driven in contravention of section 3 as may be prescribed."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"If any sum is deposited by any person under section 3 or as a condition of approval by the Authority under section 4 or 5, no part of such sum shall, so long as any liabilities being such liabilities as are required to be covered by a policy of insurance under this Act which have been incurred by him have not been discharged or otherwise provided for, be applicable in discharge of any other liabilities incurred by him."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"(1) An insurer or body of persons proposing to issue policies of insurance or to give securities for the purposes of this Act shall, unless incorporated in or residing within Brunei Darussalam, appoint one or more persons residing within Brunei Darussalam to act as agent for such insurer or body of persons and to accept on behalf of such insurer or body of persons service of process and of any notices required to be served or given.\n\n(2) Such insurer or body of persons shall file with the Authority the names and addresses of the person or persons appointed under subsection (1) and shall, in the event of such person or persons ceasing to reside within Brunei Darussalam or to be so appointed, within 7 days of such event, file with the Authority the names and addresses of one or more other such\n\n(3) Any process or notice required to be served or given to such insurer or body of persons shall be sufficiently served or given if addressed to any person whose name has been filed and left at or sent by post to the address which has been so filed.\n\n(4) For the purposes of sections 4(4), 5(2), 9(2), 11(3) and 15, “insurer” includes a person appointed under subsection (1).\n\n(5) Nothing in this section shall relieve any company from any obligation to register under any written law for the time being in force relating to companies. Offences in respect of certificate of insurance.\n\n(a) for the purpose of obtaining the issue of a certificate of insurance or of a certificate of security, makes any statement which is false or misleading or withholds any material information unless he establishes to the satisfaction of the court that he acted without any intent to deceive;\n\n(b) forges, alters, defaces or mutilates any certificate of insurance or certificate of security;\n\n(c) lends to or allows to be used by another person any certificate of insurance or certificate of security which such person is not entitled\n\n(d) makes or has in his possession any certificate of insurance or certificate of security which is calculated to deceive unless he establishes to the satisfaction of the court that he acted without intent to\n\n(e) issues a certificate of insurance or certificate of security which is to his knowledge false in any material particular, is guilty of an offence and liable on conviction to a fine of $8,000 and imprisonment for 3 years."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Any person guilty of an offence against this Act for which no special penalty is provided is liable, in the case of a first offence to a fine of $2,000 and in the case of a second or subsequent offence to a fine of $4,000 and imprisonment for 6 months. Officers of companies."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"If any person guilty of an offence against this Act is a company, any officer or servant in Brunei Darussalam of the company who is privy to the offence is guilty of a like offence and liable to the punishment provided in this Act for such offence. Jurisdiction of courts."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"Notwithstanding anything contained in the Criminal Procedure Code (Chapter 7), the Court of a Magistrate shall have jurisdiction to try any offence against the provisions of this Act or any rule made thereunder and may pass any sentence provided by this Act for any such offence. Power to make rules."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"The Authority may make rules for prescribing anything which may be prescribed under this Act and generally for the purpose of carrying this Act into effect, and in particular, but without prejudice to the generality of the foregoing provisions, may make rules —\n\n(a) to prescribe the forms to be used;\n\n(b) as to applications for and the issue of certificates of insurance and any other documents which may be prescribed, and as to the keeping of records of documents and the furnishing of particulars thereof or the giving of information with respect thereto;\n\n(c) as to the issues of copies of any such certificates or other documents which are lost or destroyed;\n\n(d) as to the custody, production, cancellation and surrender of any such certificates or other documents;\n\n(e) for providing that any provisions of this Act shall, in relation to motor vehicles brought into Brunei Darussalam by persons making only a temporary stay in Brunei Darussalam, have effect subject to such modifications and adaptations as may be prescribed;\n\n(f) to prescribe the penalty not exceeding a fine of $4,000 and imprisonment for 6 months with which the contravention of any rule made under this section be punishable;\n\n(g) with respect to the payment of deposits under this Act and the investment thereof or dealing therewith, the deposit of stocks or other in lieu of money, the payment of the interest or dividends from time to time accruing due on any securities in which deposits are for the time being invested and the withdrawals and transfers of Application of Act to securities."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A24","no":24,"noLabel":{"en":"Section 24."},"heading":{"en":"_____________________________"},"text":{"en":"The provisions of this Act apply in relation to securities having effect for the purposes of this Act as they apply in relation to policies of insurance, and in relation to any such security, references in the provisions to being insured to a certificate of insurance, to an insurer and to persons insured shall be construed respectively as references to the having in force of the security, to the certificate of security, to the giver of the security and to the persons whose liability is covered by the security."}},{"id":"BN-CAP-90-2014-MOTOR-VEHICLES-INSURANCE-THIRD-PARTY-RISKS-ACT-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"The Authority may by public notification either generally or for such period and subject to such conditions as may be specified in such notification exempt from any provision of this Act or any rules made thereunder any person or class or description of persons or any motor vehicles or class or description of motor vehicles."}}],"pack":"bn-p24","summary":{"en":"An Act to make provision for the protection of third parties against risks"},"titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"MOTOR VEHICLES INSURANCE THIRD PARTY RISKS ACT","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-CAP-93-2002-LABOUR-ACT"] = {"id":"BN-CAP-93-2002-LABOUR-ACT","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":132,"structureMode":"SECTION","title":{"zh":"劳动法","en":"LABOUR ACT","orig":"LABOUR ACT","vi":"Luật Lao động","th":"พระราชบัญญัติแรงงาน","id":"Undang-Undang Ketenagakerjaan","ms":"Akta Buruh"},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《CAP-93-2002-ED-LABOUR-ACT.pdf》（77 页），本次切分 132 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"CAP-93-2002-ED-LABOUR-ACT.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-CAP-93-2002-LABOUR-ACT-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Act may be cited as the Labour Act."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In this Act, unless the context otherwise requires — “agreement” means an oral engagement to work entered into in accordance with the provisions of this Act; “apprentice” means any person of either sex who has contracted to serve an employer and to learn and be taught any business, trade manufacture, undertaking, calling or employment in which workers are employed; “child” means a person under the age of 14 years; “confinement” means the delivery of a child; “contract” means a written engagement to work entered into in accordance with the provisions of this Act; “dependant” means the wife or wives of a worker, and his children, step-children and lawfully adopted children who are unmarried and under the age of 16 years and any aged or incapacitated relative whom the Commissioner is satisfied is wholly dependant upon and living with the worker; “domestic servant” means any house, stable or garden servant or car driver habitually employed in, or in connection with, the domestic services of any public or private dwelling-house, eating house, club or institution; “employer” includes the Government of Brunei and any person or body of persons, corporate or unincorporate, and the legal personal representative of a deceased employer who or which enters into any agreement or contract with any worker and the duly authorised agent or manager of such person or body of persons and, where any person (hereinafter referred to as the principal) in the course of or for the purposes of his trade or business enters into any agreement or contract with any person (hereinafter referred to as the contractor) for the execution by or under the contractor of the whole or any part of any work undertaken by the principal, the principal shall, in respect only of any liability for the payment of wages remaining unpaid for a period not exceeding 3 months, be held to be the employer; “family” means the wife or wives of a worker, and his children, stepchildren and lawfully adopted children who are unmarried and under the age of 14 years; “Health Officer” means the Director of Medical Services and includes any officer to whom, by writing under his hand, he delegates the exercise or performance of all or any of the powers or duties conferred or imposed on the Health Officer by this Act to the extent of the powers or duties so delegated; “immigrant worker” means any worker who is normally resident outside Brunei Darussalam who has come to Brunei Darussalam for the purpose of performing work in Brunei Darussalam; “industrial undertaking” means —\n\n(a) mines, quarries and other works for the extraction of minerals from the earth;\n\n(b) industries in which articles are manufactured, altered, cleaned, repaired, ornamented, finished, adapted for sale, broken up or demolished, or in which materials are transformed, including ship buildings, and the generation, transformation and transmission of electricity and motive\n\n(c) construction, reconstruction, maintenance, repair, alteration, or demolition of any building, railway, tramway, harbour, dock, pier, canal, inland waterway, road, tunnel bridge, viaduct, sewer, drain, well, telegraphic or telephonic installation, electrical undertaking, gaswork, waterworks or other work of construction, as well as the preparation for or laying the foundation of any such work\n\n(d) transport of passengers or goods by road or rail, or inland waterway, including the handling of goods at dock, quays, wharves, and warehouses, but excluding transport by hand: Provided that if, having regard to the nature of the work involved in any occupation which forms part of the industrial undertaking, His Majesty the Sultan and Yang Di-Pertuan in Council considers that such occupation should be excluded from the provisions of this Act relating to industrial occupations, he may declare, by order, that employment in such occupation shall be deemed not to be employment in an industrial undertaking for the purpose of this Act: Provided further that any undertaking of which a part only is an industrial undertaking shall not for that reason alone be deemed to be an industrial undertaking; “mine” includes any undertaking whether public or private for the extraction of any substance from under the surface of the “place of employment” means any place where work is carried on by or on behalf of any employer; “rate of pay”, “rate of wages” and “wage rate” each means the total amount of money including allowances to which a worker is entitled under his contract of service for working either for a period of time stated or implied in his contract or for the performance of each completed piece or task of work, but does\n\n(i) additional payments in respect of overtime work;\n\n(ii) additional payments by way of bonus;\n\n(iii) allowances for travelling or food;\n\n(iv) such additional payments or allowances made by reason of the special nature of work performed, as the Commissioner may Provided that in the case of a worker employed on piece rates, the ordinary rate of pay shall be calculated by dividing the period of 14 days immediately preceding the day on which the rate of pay is required to be calculated by the number of days on which such worker actually worked during such period; “recruit,” with its grammatical variations and cognate expressions, means to procure, engage, hire or supply or undertake or attempt to procure, engage, hire or supply workers for the purpose of being employed by the recruiter or by any other person, where such worker does not spontaneously offer his services at the place of employment or at a public employment office or at an office conducted by an employers’ organisation and supervised by the Government; “repatriation” means the return of a worker to his country of domicile or origin and includes the return to his house of a worker who has been brought to a place of employment by an employer from any other place within Brunei Darussalam; “shift worker” means a worker who is engaged in work which by reason of its nature requires to be carried on continuously by a succession of shifts or any other work which the Commissioner has by notice published in the Gazette declared to be shift work for the purpose of this definition; “ship” includes any vessel or boat of any nature whatsoever, engaged in navigation whether publicly or privately owned but does not include a ship of war; “wages” means all remuneration which is payable to a worker for work done in respect of his agreement or contract but does not\n\n(i) the value of any house accommodation or the supply of any food, fuel, light or water or medical attendance, or of any amenity or services excluded by general or special order of the State Secretary published in the ;\n\n(ii) any contribution paid by the employer on his own account to any pension fund or\n\n(iii) any travelling allowance or the value of any travelling concession;\n\n(iv) any sum payable to the worker to defray special expenses entailed on him by the nature of his employment; or\n\n(v) any gratuity payable on discharge or “woman” means a female of the age of 18 years or upwards; “worker” means a labourer, servant in husbandry, journeyman, artificer, handicraftsman, miner or other person engaged in manual labour or in recruiting such or in supervising in person any workman in and throughout the performance of his work, who has entered into and works under an agreement or contract with an employer, and includes an immigrant worker and any person, other than clerical staff, employed in the operation or maintenance of mechanically propelled vehicles used for transport of passengers or goods for hire or for commercial purposes, but does not include an apprentice or seaman engaged on ships articles; “worker-recruiter” means a person who, being employed as a worker, is authorised in writing by this employer to recruit, but who does not receive any remuneration or other advantage for “young person” means a person who has ceased to be a child but who is under the age of 18 years. Commissioner of Labour and other Officers."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"(1) His Majesty may, by notification in the Gazette, appoint by name or by office an officer to be styled the Commissioner of Labour, hereinafter referred to as the Commissioner, and also appoint one or more officers to be styled Deputy Commissioner of Labour or Assistant Commissioner of Labour and such other officers as may be necessary for carrying out the provisions of this Act, who, subject to such limitations as His Majesty in Council may by rule prescribe, may perform all duties imposed and exercise all powers conferred on the Commissioner by this Act.\n\n(2) If any employer is dissatisfied with any decision or order of a Deputy Commissioner of Labour or an Assistant Commissioner of Labour made or given by virtue of the provisions of the preceding subsection, he may appeal from such decision or order to the Commissioner within 14 days of the date of such decision or order being communicated to him.\n\n(3) If any employer is dissatisfied with any decision or order made or given by the Commissioner either original or by virtue of the preceding subsection, he may appeal from such decision or order to the Minister within 14 days of the date of such decision or order being communicated to him. Government inspections."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"(1) The Commissioner or Health Officer may enter at all reasonable times upon any place of employment and into any house accommodation provided by an employer for workers, and put questions concerning the workers to the employer or to any person who may be in charge of them or to the workers themselves, and the employer or such person, or any such worker, shall be legally bound to answer such questions truly to the best of his ability.\n\n(2) If the Commissioner or Health Officer has reasonable ground for suspecting that any offence has been committed against a worker, and whenever any complaint of personal ill-usage or breach of any of the provisions of this Act is made to the Commissioner or Health Officer, the Commissioner or Health Officer, as the case may be, may forthwith remove, or cause to be removed, such worker from the place of employment where he is employed for further inquiry into the matter.\n\n(3) The Commissioner or Health Officer may by order in writing require any employer to take within a reasonable time in the circumstances such steps as he considers necessary with a view to remedying defects observed in plant, layout, working methods, supervision medical or sanitary provision or other matters at any place or employment which he may have reasonable cause to believe constitute a threat to the health or safety of the Accidents to be notified."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"(1) Whenever an accident caused by machinery results in loss of life or grievous hurt to any worker the employer shall forthwith notify the Commissioner who shall at the earliest opportunity cause an examination to be made as to the cause of such accident: Provided that a notice served by the employer on the Commissioner under the provisions of section 13 of the Workmen’s Compensation Act (Chapter 74), shall, if it is therein stated that the accident was caused by machinery, be deemed to be notification for the purposes of this subsection.\n\n(2) Where an examination of any machinery is required by virtue of the provisions of subsection (1), no alteration shall be made to that machinery until such examination has been carried out.\n\n(3) In this section “machinery” means any engine, electrical machinery, powerplant, boiler, sawmill, gasometer, gas-holder, generator, gearing and appliances for transmission of power and all appurtenances of any of the above, but does not include machinery driven by manual power, machinery for driving any vehicle or marine machinery. Inspection of documents substances etc."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"The Commissioner or Health Officer may —\n\n(a) call for and examine all contracts, registers, books of account and other documents concerning any workers or relating to their employment; and\n\n(b) take or remove for purposes of analysis samples of materials and substances used or handled, subject to the employer or his representative being notified of any samples or substances taken or removed for such purposes. Power of summons and institution of proceedings."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"(1) Whenever the Commissioner has reasonable grounds for suspicion that any offence under this Act or any rule made thereunder has been committed or wishes to inquire into any matter concerning disputes as to wages, wrongful termination of agreement or contract, misconduct, food, medical attendance, death, mining usage and mining complaint, Government inspection, sanitation or any other matter relating to employer and worker dealt with under the provisions of this Act or any rule made thereunder, the Commissioner may summon any person who he has reason to believe can give information respecting the subject-matter of the enquiry, and the person so summoned shall be legally bound to attend at the time and place specified in the summons and to answer truthfully all questions which the Commissioner may put to him.\n\n(2) If the Commissioner is of the opinion that an offence has been committed or that any complaint is well founded he may institute such proceedings criminal or civil for and in the name of the worker as he shall deem necessary in the circumstances."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"(1) Any employer or other person who wilfully obstructs or impedes any entry, inquiry or investigation made under this Act or wilfully obstructs the service of, or obedience to, any summons and any person summoned who neglects to attend as required in such summons, and any person who commits in that connection any offence described in Chapter X of the Penal Code (Chapter 22) shall be punished as provided in Chapter X of the Penal\n\n(2) Any employer who contravenes or fails to comply with any order of the Commissioner or Health Officer made under section 4 or fails to report an accident, or alters, or causes, or permits to be altered any machinery, in contravention of the provisions of section 5 shall be guilty of an offence: Penalty, a fine of $1,500 and in default thereof imprisonment for 6 months. Power to make rules."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"(1) His Majesty in Council may from time to time make rules generally for carrying out the provisions of this Part.\n\n(2) Without prejudice to the generality of the foregoing such rules may provide for any matter which by this Part is to be, or may be, prescribed.\n\n(3) Any such rule may provide a penalty for the breach or contravention thereof not exceeding a fine of $600 or in default thereof imprisonment for a term not exceeding 3 months.\n\nAGREEMENTS AND CONTRACTS Terms of agreement."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"(1) An agreement may be entered into for any period not exceeding one month or for any number of days’ work not exceeding 26 or for the performance by a worker for an employer of any specified piece of work capable of being completed within one month from the commencement of the work. Every agreement shall, subject to any stipulation to the contrary, terminate on the last day of the period agreed upon or upon the completion of the specified number of days’ work or piece of work, as the case may be: Provided that each party to an agreement for a period not exceeding one month shall on the termination of such agreement in the manner aforesaid be conclusively presumed to have entered into a fresh agreement upon the same terms and conditions as those of the agreement so terminated unless notice has been given previously by either party to such agreement in accordance with the provisions of section 12.\n\n(2) In the absence of proof to the contrary every agreement shall be presumed to be for a period of one month."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"In the case of a worker employed on an agreement for a period of a week or more and paid according to the number of days’ work performed, an employer shall provide work suitable to the capacity of such worker for not less than 5½ days in every week with the exception of prescribed holidays and Fridays (or such other rest day as may be substituted for a Friday by agreement between the employer and the worker, entered into not less than 3 days before the rest is taken) and if he is unable or fails to provide such work on such number of days whereon the worker presents himself for work and is fit to work the employer shall nevertheless be bound to pay to the worker in respect of each of such days, wages at not less than his usual rate of pay, including cost of living allowance, if any, or if the worker is on piece rates at not less than the average of his previous week’s earnings or if he has not been working, at the average rate during the last full week’s work earned by a similar class of worker engaged on similar work: Provided that if such day is a work day, other than a Saturday, the employer shall pay at a rate as if a whole day’s work had been performed. Termination of agreement by notice."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A12","no":12,"noLabel":{"en":"Section 12."},"text":{"en":"(1) Either party to an agreement for a period of time may terminate such agreement on the expiration of due notice given by him to the other party of his intention so to do; the length of the notice to be given shall, unless otherwise stipulated by the terms of the agreement, be equal to the period of the agreement to be terminated: Provided that in no case shall it be necessary to give notice exceeding in length one month or in the case of domestic servants 14 days.\n\n(2) Such notice may be either oral or written and may be given at any time and the day on which notice is given shall be included in the period Termination of agreement without notice by either party."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A13","no":13,"noLabel":{"en":"Section 13."},"text":{"en":"Either party to an agreement may terminate the same without notice upon payment to the other party of a sum equal to the amount of wages which would have accrued to the worker during the period of the notice required by section 12. Dismissal by the employer without notice."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A14","no":14,"noLabel":{"en":"Section 14."},"text":{"en":"An employer shall not dismiss a worker employed without notice except in the following circumstances —\n\n(a) where the worker is guilty of misconduct, whether in the course of his duties or not, inconsistent with the fulfilment of the express or implied conditions of his agreement;\n\n(b) for wilful disobedience to lawful orders given by the\n\n(c) for lack of the skill which the worker expressly or implicitly warrants himself to posses;\n\n(d) for habitual or substantial neglect of his duties;\n\n(e) for absence from work without leave from the employer or absence without other reasonable excuse. Cancellation of agreement by Commissioner."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A15","no":15,"noLabel":{"en":"Section 15."},"text":{"en":"An agreement may be cancelled by an order of the Commissioner if the worker is subject to ill-usage in person or property and the Commissioner may by such order award the worker reasonable compensation. Capacity to enter into an agreement."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A16","no":16,"noLabel":{"en":"Section 16."},"text":{"en":"Notwithstanding anything contained in any written law any young person shall be capable of entering into an agreement."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A17","no":17,"noLabel":{"en":"Section 17."},"text":{"en":"(1) Every employer who fails to make payment in accordance with the provisions of section 11 or contravenes the provisions of section 14 shall be guilty of an offence: Penalty, a fine of $1,500 or in default thereof imprisonment for 6 months.\n\n(2) A court may in any proceedings under this section order the payment of such wages as are found due by an employer together with such sum or sums for damages, costs, and expenses as it shall deem fit. Certain contracts excluded."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A18","no":18,"noLabel":{"en":"Section 18."},"text":{"en":"This Chapter and any rules made thereunder do not apply to contracts of apprenticeship. Contracts to be in writing."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A19","no":19,"noLabel":{"en":"Section 19."},"text":{"en":"(1) When an engagement with a worker —\n\n(a) is made for a period exceeding one month or a number of working days exceeding 26;\n\n(b) is made or the performance of a specified piece of work for an employer, incapable of being completed within one month from the commencement of the work;\n\n(c) stipulates conditions of employment which differ materially from those customary in the district of employment for similar work, the engagement shall be in writing and shall be signed by both parties: Provided that a worker unable to sign may indicate his consent by affixing thereto the impression of his thumb.\n\n(2) If the omission to make in writing any contract, which is required by this section, is due to the wilful act or negligence of the employer, the worker shall, without prejudice to any right he may have to sue for damages for breach of contract be entitled to apply to the Commissioner for cancellation of the contract. Contents of contract."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A20","no":20,"noLabel":{"en":"Section 20."},"text":{"en":"Every contract shall contain in clear and unambiguous terms all that may be necessary to define the rights and obligations of the parties thereto and without prejudice to the generality of the foregoing shall in all cases include the following particulars —\n\n(a) the name of the employer or group of employers and, where practicable, of the undertaking and the place of\n\n(b) the name of the worker, the place of engagement and the place of origin of the worker, and any other particulars necessary for his identification;\n\n(c) where possible the names and addresses of the next of\n\n(d) the nature of the employment;\n\n(e) the duration of the employment and the method of calculating this duration;\n\n(f) the appropriate period of notice to be given by the party wishing to terminate the contract, due regard being had to the provisions of section 27 and to the fact that such provisions refer to an equitable settlement of monetary and other question;\n\n(g) the rates of wages and method of calculation thereof, the manner and periodicity of payment of wages, the advances of wages, if any, and the manner of repayment of any such advances;\n\n(h) the measures to be taken to provide for the welfare of the worker and any dependant who may accompany him under the terms of the contract;\n\n(i) the conditions of repatriation; and\n\n(j) any special conditions of the contract. Contract not ordinarily binding on family dependants."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A21","no":21,"noLabel":{"en":"Section 21."},"text":{"en":"No contract shall be deemed to be binding on the family or dependants of the worker, unless it contains an express provision to that Attestation of contracts."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A22","no":22,"noLabel":{"en":"Section 22."},"text":{"en":"(1) Every contract shall be presented for attestation to the\n\n(2) Before attesting any such contract the Commissioner shall —\n\n(a) ascertain that the worker has freely consented to the contract and that his consent has not been obtained by coercion or undue influence or as the result of misrepresentation or mistake; and\n\n(b) satisfy himself that —\n\n(i) the contract is in due legal form;\n\n(ii) the terms of the contract are in accordance with the requirements of this Act;\n\n(iii) the worker has fully understood the terms of the contract before signing it or otherwise indicating his\n\n(iv) the provisions relating to medical examination set out in section 23 have been complied with; and\n\n(v) the worker declares himself not bound by any previous\n\n(3) The Commissioner may refuse to attest any contract in respect of which he is not satisfied in regard to any of the matters specified in subsection (2) of this section, and any contract which the Commissioner has refused to attest shall have no further validity.\n\n(4) A contract which has not been presented to the Commissioner for attestation shall only be enforceable as an agreement under the provisions of Chapter IV of this Part, but each of the parties shall be entitled to have it presented for attestation at any time prior to the expiry of the period for which it was made.\n\n(5) If the omission to present the contract for attestation was due to the wilful act or the negligence of either party the other party shall be entitled to apply to the Commissioner for the cancellation of the contract.\n\n(6) 4 copies of every contract attested under the provisions of this Chapter shall be attested including the original. One copy shall be delivered to the employer, one to the worker or in the case of a gang to one of their number, one to the Assistant Commissioner in the district of employment and the original shall be retained by the Commissioner who shall keep a record of all such contracts.\n\n(7) Notwithstanding the other provisions of this section, the Commissioner may, in his discretion, approve a standard form of contract to be used by any particular person or firm and when such approved form of contract is used individual attestation by the Commissioner shall not be necessary, but the employer shall render to the Commissioner a quarterly return of all persons newly employed during each quarter under such approved form of contract together with a certificate that the terms and conditions thereof were read over to and understood by the worker before he signed such contract. Medical examinations."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A23","no":23,"noLabel":{"en":"Section 23."},"text":{"en":"(1) Every worker who enters into a contract shall be medically examined at the expense of the employer.\n\n(2) As a general rule the worker shall be medically examined and a medical certificate issued before the attestation of the contract.\n\n(3) Where it has not been possible for the worker to be medically examined before the attestation of the contract, the Commissioner when attesting the contract shall endorse it to that effect and the worker shall be examined at the earliest opportunity.\n\n(4) The Commissioner may, by endorsement on the contract, exempt from the requirement of medical examination workers entering into contracts for —\n\n(a) employment in agricultural undertakings not employing more than such number of workers as may be prescribed;\n\n(b) employment in the vicinity of workers, homes —\n\n(i) in agricultural work;\n\n(ii) in non-agricultural work which the Commissioner is satisfied is not a dangerous character or likely to be injurious to the health of the workers. Capacity to enter into a contract."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A24","no":24,"noLabel":{"en":"Section 24."},"text":{"en":"(1) A person whose apparent age is less than 16 years shall not be capable of entering into contract.\n\n(2) Notwithstanding anything contained in any written law a person whose apparent age exceeds 16 years but is less than 18 years shall be capable of entering into a contract for employment in an occupation approved by the Commissioner as not being injurious to the moral and physical development of non-adults. Maximum duration of contracts."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A25","no":25,"noLabel":{"en":"Section 25."},"text":{"en":"(1) (a) the maximum duration that may be stipulated or implied in any contract involving a journey within Brunei Darussalam and the Malaysian territories of Sarawak and Sabah from the place of recruitment to the place of employment, shall in no case exceed 12 months if the worker is not accompanied by his family;\n\n(b) the maximum duration which may be stipulated or implied in any contract involving a journey other than a journey referred to in the preceding subsection from the place of recruitment to the place of employment shall in no case exceed 2 years if the worker is not accompanied by his family or 3 years if the worker is accompanied by\n\n(2) The Commissioner may, after consultation with any employers’ and workers’ organisations, representative of the interests concerned, exclude from the application of this section contracts entered into between employers and literate workers whose freedom of choice in employment is satisfactorily safeguarded; such exclusion may apply generally, or to the workers in any specified industry of undertaking or to special groups of Transfer to other employment."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A26","no":26,"noLabel":{"en":"Section 26."},"text":{"en":"(1) The transfer of any contract from one employer to another shall be subject to the consent of the worker and the endorsement of the transfer upon the contract by the Commissioner.\n\n(2) Before endorsing the upon the the\n\n(a) shall ascertain that the worker has freely consented to the transfer and that his consent has not been obtained by coercion or undue influence or as the result of misrepresentation or mistake; and\n\n(b) in any case in which by such transfer the worker —\n\n(i) will change his form of employment from one the subject of an exemption made under the provisions of subsection (4) of section 23; or\n\n(ii) will be subject to such change in conditions as in the opinion of the Commissioner renders such a course may require the worker to be medically examined or re-examined as the case Termination of contract."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A27","no":27,"noLabel":{"en":"Section 27."},"text":{"en":"(1) A contract shall be terminated —\n\n(a) by the expiry of the period for which it was made; or\n\n(b) by the death of the employer or worker before the expiry of the period for which it was made.\n\n(2) The termination of a contract by the death of the worker shall be without prejudice to the legal claims of any person entitled thereto.\n\n(3) If the employer is unable to fulfil a contract or if owing to sickness or accident the worker is unable to fulfil the contract, the contract may be terminated with the consent of the Commissioner subject to conditions safeguarding the right of the worker to wages earned, any deferred pay due to him, any compensation due to him in respect of accident or disease, and his right to repatriation.\n\n(4) A contract may be terminated by agreement between the parties with the consent of the Commissioner subject to conditions safeguarding the worker from the loss of his right to repatriation unless the agreement for the termination of the contract otherwise provides and to the Commissioner\n\n(a) that the worker has freely consented to the termination and that his consent has not been obtained by coercion or undue influence or as the result of misrepresentation or mistake; and\n\n(b) that all monetary liabilities between the parties have been settled.\n\n(5) A contract other than a contract to perform some specific work without reference to time, may be terminated by either party giving to the other, notice of such termination in accordance with the terms of the contract; the minimum requirements of which shall be —\n\n(a) where the duration is for more than one month the period of notice shall be not less than 14 days and may be given only after the expiry of the first month of employment; or\n\n(b) where the duration is for one month or less the period of notice shall be not less than 7 days: Provided that except where the Commissioner in his discretion shall otherwise permit the period of notice stipulated in the contract shall not Provided further that an equitable settlement of monetary and other conditions including the question of repatriation shall be agreed upon between the worker and the employer and in default of such agreement either party may refer the matter to the Commissioner who shall make such order, including the award of any subsistence expenses reasonably incurred pending such order, as may be just and equitable. Cancellation of contract by Commissioner."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A28","no":28,"noLabel":{"en":"Section 28."},"text":{"en":"A contract may be cancelled by an order of the Commissioner if the worker is subject to ill-usage in person or property and in such event the Commissioner may award the worker reasonable compensation. Duration of re-engagement contracts."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A29","no":29,"noLabel":{"en":"Section 29."},"text":{"en":"(1) The maximum duration that may be stipulated in any re-engagement contract on the expiry of the period for which the original contract was made shall be three-quarters of that prescribed in section 25 but in no case exceeding one year.\n\n(2) Where the duration to be stipulated in any re-engagement contract, together with the period already served under the expired contract, involves the separation of any worker from his family for more than the respective periods prescribed in section 25 the worker shall not begin the service stipulated in the re-engagement contract until he has had the opportunity to return home at the employer’s expense: Provided that the Commissioner may grant exemption from this provision whenever its application is impracticable or undesirable. Provisions applicable to re-engagement contracts."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A30","no":30,"noLabel":{"en":"Section 30."},"text":{"en":"Except as provided in section 29 all the provisions of the preceding sections of this Chapter shall apply to re-engagement contracts: Provided that the Commissioner may in his discretion exempt such contracts from the provisions of section 22 relating to attestation and of section 23 relating to medical examination subject to such terms and conditions as may be prescribed. Summary of Chapter to be brought to notice of workers."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A31","no":31,"noLabel":{"en":"Section 31."},"text":{"en":"(1) The Commissioner shall, where necessary, cause concise summaries of this Chapter to be printed in Malay and in a language known to the workers and shall make such summaries available to the employer and workers concerned.\n\n(2) Where necessary, the employer shall be required by the Commissioner to post such summaries in a language known to the workers in conspicuous places at the place of employment. Contracts for service outside Brunei Darussalam."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A32","no":32,"noLabel":{"en":"Section 32."},"text":{"en":"Where a contract made in Brunei Darussalam relates to employment in another territory (in this section referred to as the territory of\n\n(a) the attestation of the contract required by section 22 shall take place before the worker leaves Brunei Darussalam;\n\n(b) the measures required by subsection (6) of section 22 shall be taken by the Commissioner in Brunei Darussalam;\n\n(c) the medical examination required by section 23 shall take place at the latest at the place of departure of the worker from Brunei Darussalam;\n\n(d) a person whose apparent age is less than either the minimum age prescribed in section 24 or the minimum age of capacity for entering into a contract allowed by the law of the territory of employment if such minimum age is higher than that prescribed in section 24 shall not be capable of entering into a contract;\n\n(e) the contract shall contain a proviso that it is not transferable unless such transfer is endorsed on the contract by a public officer of the territory of employment;\n\n(f) the duration stipulated in the contract shall not exceed either the maximum period prescribed in section 25 or the maximum period prescribed by the law of the territory of employment whichever is the less;\n\n(g) if the laws of the territory of employment are substantially the same as this Chapter the conditions under which the contract is subject to termination and any question of exemption from liability for repatriation shall be determined by the law of the territory of\n\n(h) if the laws of the territory of employment differ from the laws of Brunei in respect to repatriation the Commissioner may require such deposit or security from the employer as he deems necessary and such deposit or security may be used to defray the costs of repatriation at the discretion of the Commissioner;\n\n(i) the Commissioner shall co-operate with the appropriate authority of the territory of employment to ensure the application of the provisions of subsection (2) of section 98;\n\n(j) the period of service stipulated in any re-engagement contract shall not exceed either the maximum period allowed by the provisions of section 30 or if the maximum period allowed by the law of the territory of employment is less, then such lesser period. Extraterritorial contracts for employment in Brunei Darussalam."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A33","no":33,"noLabel":{"en":"Section 33."},"heading":{"en":"Contracts of Apprenticeship"},"text":{"en":"When a contract made in another territory (in this section referred to as the territory of origin) relates to employment in Brunei Darussalam —\n\n(a) if such territory of origin has enacted laws substantially the same as this Chapter and all the provisions of such laws have been complied with prior to worker leaving such territory of origin, then —\n\n(i) the endorsement of a transfer on a contract shall be made by the Commissioner as provided in section 26;\n\n(ii) the conditions under which the contract is subject to termination shall be determined by the provisions of this Act and any rules made thereunder;\n\n(iii) if the employer fails to fulfil his obligations in respect of repatriation the said obligations may be discharged by the Commissioner as provided in section 96 and such expenses may be recovered from the employer as a debt due to the Government;\n\n(iv) the authority which may exempt the employer from liability for repatriation expenses and exercise any other powers conferred upon a competent authority in the territory of origin shall be the Commissioner;\n\n(v) the co-operate with the appropriate authority of the territory of origin to ensure the application of the provisions of subsection (2) of\n\n(vi) the duration stipulated in any re-engagement contract shall not exceed either the maximum period allowed by the law of the territory of origin, which ever is less;\n\n(b) If such territory has not enacted laws substantially the same as this Chapter or has not complied with any provisions of the law in respect of any contract then the whole of the provisions of this Chapter or such portion thereof as has not been complied with shall be complied with immediately upon the arrival of the worker in Brunei Darussalam and thereafter the provisions of this Chapter shall be deemed to apply mutatis mutandis as if such contract had been entered into in Brunei Darussalam."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A34","no":34,"noLabel":{"en":"Section 34."},"text":{"en":"Any employer who fails to comply with any order made by the Commissioner in pursuance of the provisions of this Chapter or who makes with a worker a contract contrary to the provisions of this Chapter shall be guilty of an offence: Penalty, a fine of $1,500 and imprisonment for 6 Contracts of apprenticeship of young persons under 16."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A35","no":35,"noLabel":{"en":"Section 35."},"text":{"en":"(1) The parent, or in the case of an orphan the guardian, of a young person under the age of 16 years may, with the consent of such person, execute a written contract of apprenticeship, apprenticing such person to an employer to train him or have him trained systematically for a prescribed trade or employment for any period not exceeding 5 years.\n\n(2) Whenever any young person under the age of 16 years is without known parent or guardian, the Commissioner may authorise the apprenticeship of such young person and may appoint some fit and proper person to execute the written contract of apprenticeship and act generally as guardian of such young person. Contracts of apprenticeship of young persons over 16."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A36","no":36,"noLabel":{"en":"Section 36."},"text":{"en":"Any young person above the age of 16 years or any person above the age of 18 years not being under any contract of apprenticeship may apprentice himself for any period not exceeding 5 years to an employer in any prescribed trade or employment."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A37","no":37,"noLabel":{"en":"Section 37."},"text":{"en":"Every contract of apprenticeship may with the consent of the parties thereto be assigned."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A38","no":38,"noLabel":{"en":"Section 38."},"text":{"en":"Every contract of apprenticeship and every assignment thereof shall be in writing and no such contract shall be valid unless attested by and made with the approval of Commissioner certified in writing under his hand on the contract of apprenticeship or assignment. Duties of attesting officer."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A39","no":39,"noLabel":{"en":"Section 39."},"text":{"en":"Before attesting any contract of apprenticeship the Commissioner shall satisfy himself —\n\n(a) that the employer is a fit and proper person and able and having facilities sufficient to instruct the apprentice in the trade or\n\n(b) that the apprentice has consented to such contract and that his consent has not been obtained by coercion, or undue influence or as the result of misrepresentation or mistake;\n\n(c) that the apprentice has been medically examined and certified by a registered medical practitioner to be physically and mentally fit to be employed and trained in the trade or employment specified in such contract;\n\n(d) that the parties to such contract have fully understood the terms of the contract before signing it or otherwise indicating assent;\n\n(e) that provision has been made in such contract as to how any remuneration in cash or otherwise due to the apprentice shall be determined and as to the scale of increase in remuneration during the course of the apprenticeship;\n\n(f) that provision has been made in such contract for payment of such remuneration to the apprentice during illness and during\n\n(g) that the terms of such contract are in accordance with any rules made under the provisions of this Part. Certificate of service on discharge."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A40","no":40,"noLabel":{"en":"Section 40."},"text":{"en":"(1) Whenever for any reason including the completion of his contract of apprenticeship an apprentice ceases to be employed by an employer it shall be the duty of the employer to supply the apprentice with a statement in the prescribed form setting forth the service of the apprentice.\n\n(2) The employer shall forward a copy of such statement to the Commissioner, who shall endorse a note thereof on every copy of the contract of apprenticeship submitted to him for that purpose by any of the parties to such contract. Retention of apprentices after expiry of contracts."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A41","no":41,"noLabel":{"en":"Section 41."},"text":{"en":"If any person with whom an apprentice has been placed retains such apprentice in his service after the stipulated period of service has expired without any agreement between the parties for the payment of wages, the apprentice shall be entitled to recover from the person so retaining him wages at the ordinary current rate payable for service similar to that performed by such apprentice. Suspension and discharge."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A42","no":42,"noLabel":{"en":"Section 42."},"text":{"en":"(1) In any case where an apprentice so misconducts himself or proves himself to be so incapable that if he were an employee other than an apprentice it would be reasonable for his employer to discharge him, the employer may suspend him and apply forthwith to the Commissioner for leave to discharge him.\n\n(2) The Commissioner shall enquire into the circumstances and where such leave is granted the employer shall be entitled to discharge the apprentice as from the date on which he was suspended and as from such date the contract of apprenticeship shall be deemed to be cancelled.\n\n(3) Where such leave is refused the Commissioner may make such order as he thinks fit with respect to payment of wages to the apprentice in respect of the period of his suspension. If no such order is made, the employer shall pay to the apprentice all wages that would have been payable to him in respect of such period had he not been suspended.\n\n(4) If the employer, notwithstanding that leave to discharge the apprentice has been refused by the Commissioner, discharges the apprentice, such discharge shall for all purposes be conclusive proof of a breach by the employer of the contract of apprenticeship.\n\n(5) Where an employer, without proceeding in accordance with the foregoing provisions of this section, discharges or purports to discharge an apprentice, or, having suspended him does not within 3 days thereafter make application as aforesaid for leave to discharge him, the apprentice within 7 days after such discharge or within 10 days after such suspension, as the case may be, may apply to the Commissioner for relief from such discharge or suspension and thereupon the provisions of the section shall apply in like manner as if the employer had proceeded in accordance with subsection (1)\n\n(6) The Commissioner may fix an amount that shall be payable to the apprentice as damages for breach of the contract of apprenticeship in the event of the employer discharging him contrary to the provisions of this section. Such amount shall be in addition to the amount of wages payable in respect of the period of suspension.\n\n(7) Any person aggrieved by any decision or order of the Commissioner under this section may appeal against such decision or order to a magistrate who may hear and determine such appeal either in open court or in chambers as he may think fit and may make such order as to costs as he may think fit."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A43","no":43,"noLabel":{"en":"Section 43."},"text":{"en":"Any employer who fails to comply with any order made by the Commissioner in pursuance of the provisions of this Chapter or makes a contract of apprenticeship contrary to the provisions of this Chapter shall be guilty of an offence: Penalty, a fine of $1,500 or in default thereof imprisonment for a term of 6 months. Power to make rules."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A44","no":44,"noLabel":{"en":"Section 44."},"text":{"en":"(1) His Majesty in Council may from time to time make rules generally for carrying out the provisions of this Part.\n\n(2) Without prejudice to the generality of the foregoing power such rules may —\n\n(a) provide for any matter which by this Part is to be or may be\n\n(b) prescribed the form of contracts of apprenticeship and the terms and conditions upon which such contracts may be lawfully entered into, and the duties and obligations of apprentices and their\n\n(c) provide for the registration of contracts of apprenticeship;\n\n(d) stipulate the number of apprentices who may be apprenticed during a specified period in any specified trade or employment;\n\n(e) stipulate the conditions governing the entry of young persons under the age of 16 years into apprenticeship;\n\n(f) prescribed the mutual rights and obligations of employer and apprentice;\n\n(g) provide for the supervision to be established over apprenticeship, particularly with a view to ensuring that the regulations governing apprenticeship and the terms of any contract of apprenticeship are observed, that the training is satisfactory and that there is reasonable uniformity in the conditions of apprenticeship;\n\n(h) provide for the holding of examinations of apprentices on the expiry of the period of apprenticeship and where necessary in the course of apprenticeship; and for determining the methods of organising such examinations and for the issue of certificates based on the results thereof;\n\n(i) prescribe the fees to be paid and by whom payable for attestations, endorsements or registrations effected or any acts required to be done in pursuance of the provisions of this Part or of any rules made thereunder.\n\n(3) Any such rule may provide a penalty for the breach or contravention thereof not exceeding a fine of $600 or in default thereof imprisonment for a term not exceeding 3 months.\n\nRECRUITING OF WORKERS"}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A45","no":45,"noLabel":{"en":"Section 45."},"text":{"en":"The Minister may, by notification in the Gazette, except in respect of recruiting by professional recruiters, exempt from the provisions of this Part —\n\n(a) the recruiting of workers by or on behalf of employers who do not employ more than such number of workers as shall from time to time be fixed by such notification;\n\n(b) the recruiting of workers within a specified area or a specified distance from the place of employment; or\n\n(c) the recruiting of personal or domestic servants. Public officers etc."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A46","no":46,"noLabel":{"en":"Section 46."},"text":{"en":"Public officers shall not recruit for private undertaking either directly or indirectly except when the recruited workers are to be employed on works of public utility for the execution of which private undertakings are acting as contractors for a public authority. Persons who recruit to be licensed."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A47","no":47,"noLabel":{"en":"Section 47."},"text":{"en":"(1) Subject to the provisions of subsection (6) of this section, no person shall recruit workers unless he is licensed in that behalf under the provisions of this Part or unless he has obtained a licence to recruit issued by a territory under laws substantially the same as this Part and has produced such licence to the Commissioner who may, on being satisfied in accordance with the provisions of the next succeeding subsection, countersign the same and such licence shall thereupon be deemed to be licence issued under the provisions of this Part.\n\n(2) Every person desirous of obtaining a licence under this section shall apply to the Commissioner who may in his discretion issue a licence —\n\n(a) if he is satisfied that the applicant is a fit and proper person to be granted a licence;\n\n(b) if any security prescribed has been furnished; and\n\n(c) if he is satisfied that adequate provision has been made for safeguarding the health and welfare of the workers to be recruited; and\n\n(d) if he is satisfied that the person is proposing to recruit for a public department or authority or for a specified employer or association of employers.\n\n(3) A licence shall be subject to such conditions as may be endorsed thereon, and shall not be transferable.\n\n(4) No licence shall be issued for a period exceeding one year, but if the Commissioner is satisfied that the conditions on which it was granted have been complied with he may renew such licence for such period not exceeding one year as he may think fit.\n\n(5) The Commissioner may cancel any licence in any case where the licensee has been convicted of an offence under this Part or the rules made thereunder or has not complied with the conditions under which it was granted or is guilty of conduct which in the opinion of the Commissioner renders him no longer a fit and proper person to hold a licence; and the Commissioner may suspend any licence pending the decision of the court or the making of any enquiry which he shall consider necessary.\n\n(6) His Majesty in Council may by rules made hereunder and subject to such conditions as he may therein prescribe exempt worker-recruiters from the provisions of this section. Non-adults not to be recruited."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A48","no":48,"noLabel":{"en":"Section 48."},"text":{"en":"Persons under the age of 16 years shall not be recruited: Provided that young persons under that age may be recruited with the consent of their parents or guardians for employment upon light work in an occupation approved by the Commissioner. Family not deemed recruited."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A49","no":49,"noLabel":{"en":"Section 49."},"text":{"en":"The recruiting of the head of a family shall not be deemed to involve the recruiting of any member of his family. Examination of workers."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A50","no":50,"noLabel":{"en":"Section 50."},"text":{"en":"(1) Every recruited worker shall —\n\n(a) be brought before the Commissioner or officer in charge of an administrative district;\n\n(b) be medically examined at the expense of the recruiter or as nearly as may be convenient to the place of recruitment and in accordance with rules made under this Part.\n\n(2) The Commissioner or officer before whom any recruited worker is brought shall satisfy himself that the provisions of this Part and the rules made thereunder have been observed and that the worker has not been subject to illegal pressure or recruited by misrepresentation or mistake. Expenses of worker or burial of worker during journey."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A51","no":51,"noLabel":{"en":"Section 51."},"text":{"en":"(1) The expenses of the journey of recruited workers and their dependants to the place of employment, including all the expenses incurred for their protection during the journey, shall be borne and transport and necessaries for the journey shall be provided by the recruiter(not being a worker recruiter) or employer to a standard and on conditions in accordance with rules made under this Part.\n\n(2) In the event of the death of any recruited worker or of any dependant occurring during any journey to the place of employment from the place of recruitment the recruiter shall provide decent burial and pay the reasonable expenses of burial. Return of workers."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A52","no":52,"noLabel":{"en":"Section 52."},"text":{"en":"A recruited worker who —\n\n(a) becomes incapacitated by sickness or accident during the journey to his place of employment;\n\n(b) is found on medical examination to be unfit for\n\n(c) is not engaged after being recruited for a reason for which he is not responsible; or\n\n(d) is found by the Commissioner or officer in charge of an administrative to have been by misrepresentation or mistake, and the dependants of such recruited worker, and any dependant of a recruited worker who dies during the journey to the place of employment, shall be returned to their place of origin, or place of engagement if the latter be nearer to the place of employment and the laws of the place of engagement permit, at the expense of the recruiter or employer in accordance with rules made under this Part. Workers recruiters."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A53","no":53,"noLabel":{"en":"Section 53."},"text":{"en":"The provisions of this Part and the rules made thereunder shall, unless otherwise expressly provided, apply to worker-recruiters as if they were licensees: Provided that worker-recruiters shall recruit only in such areas as may be specified by the Commissioner and shall not make advances of wages to recruited workers. Extraterritorial recruiting."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A54","no":54,"noLabel":{"en":"Section 54."},"text":{"en":"(1) Any person acting or proposing to act as a recruiter in a territory of origin outside Brunei Darussalam for the purpose of recruiting workers for employment in Brunei Darussalam shall, before leaving Brunei Darussalam to do so, first obtain a licence under this Part, and thereafter, if such territory provides in its laws provisions substantially the same as this Part, shall also obtain such licence as may be required under such laws and shall comply with all laws of such territory relating to recruiting and shall in any event, whether required by such laws or not, fulfil all the obligations of this Part of this Act as if the same were written into the laws of such territory and its provisions, where possible, shall be observed both prior to the departure of the worker from the territory of recruitment as well as upon arrival in Brunei Darussalam.\n\n(2) Any agreement or contract of employment entered into with a worker arising from a contravention of the provisions of the last preceding subsection may be declared void by the Commissioner and thereupon any such worker and his family may be repatriated by the Commissioner and all costs of such repatriation shall be recovered from any security or borne by the offending recruiter or employer and may be recovered as a debt due to"}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A55","no":55,"noLabel":{"en":"Section 55."},"text":{"en":"Any person who recruits or attempts to recruit any person contrary to the provisions of this Chapter or contravenes or fails to comply with any of the provisions of this Chapter or any special conditions to which his licence is subject, shall be guilty of an offence: Penalty, a fine of $1,500 and imprisonment for 6 months. Power to make rules."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A56","no":56,"noLabel":{"en":"Section 56."},"text":{"en":"(1) His Majesty in Council may, by notification in the Gazette, make rules not inconsistent with this part for the purpose of giving effect thereto or to any of the provisions of the Recruiting of Indigenous Workers Convention 1936 and without prejudice to the generality of the foregoing power, he may by rule provide for —\n\n(a) the manner and form in which applications shall be made for licences, the particulars to be furnished upon every such application, the conditions under which any licence may be issued, the form of licences, the fees payable therefore, and particulars to be set forth\n\n(b) the security to be furnished by applicants for licences;\n\n(c) the records to be kept by licensees;\n\n(d) the remuneration to be paid to the agents of licensees;\n\n(e) the prohibition of recruiting within any specified area;\n\n(f) the supervision of worker-recruiters;\n\n(g) the documents to be given to the recruited workers by licensees;\n\n(h) the conditions under which recruited workers may be accompanied by dependants;\n\n(i) the provision of necessaries and transport for recruited workers and dependants from the place of recruitment to the place of employment and the conditions applicable to the journey;\n\n(j) the amount of wages which may be paid in advance to recruited workers and the conditions under which advances of wages may be made;\n\n(k) the fees to be paid and by whom payable for any licences issued, attestations, endorsements or registrations effected or any other acts required to be done in pursuance of the provisions of this Act or any rules made thereunder;\n\n(l) the establishment of a fund or other method to make provision for securing the payment of any expenses of recruitment or transport of workers upon such terms and conditions and subject to such control as he deems necessary and for providing that any such fund may be administered in conjunction with any fund established under paragraph (c) of subsection (2) of section 121;\n\n(m) anything which by this Part is to be or may be prescribed, or as to which rules are to be made.\n\n(2) Any such rule may provide a penalty for the breach or contravention thereof not exceeding a fine of $1,500 or in default thereof imprisonment for a term not exceeding 6 months.\n\nCONDITIONS OF EMPLOYMENT Special Places of Employment"}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A57","no":57,"noLabel":{"en":"Section 57."},"text":{"en":"(1) This Chapter and any rule made thereunder shall apply only to the places of employment in respect of which a declaration is made in accordance with subsection (2).\n\n(2) His Majesty in Council may by notification in the Gazette, declare that the provisions of this Chapter or of such sections thereof as may be specified in such notification shall apply to any place of employment either generally or specifically and be complied with by employer of the workers thereon or therein. Name to be painted on notice board and displayed."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A58","no":58,"noLabel":{"en":"Section 58."},"text":{"en":"Every employer shall cause to be erected and exhibited in a conspicuous place at the place of employment a notice board on which shall be painted in easily legible characters, the name of the place of employment and the name and address of the person responsible for its management and, if the employer is a company, the situation of the registered office of the Register of workers."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A59","no":59,"noLabel":{"en":"Section 59."},"text":{"en":"Every employer shall keep a register of all workers in his employment in the prescribed form. Housing, water supply and sanitation."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A60","no":60,"noLabel":{"en":"Section 60."},"text":{"en":"(1) Every employer shall provide and maintain —\n\n(a) sufficient and hygienic house accommodation;\n\n(b) a sufficient supply of wholesome water; and\n\n(c) sufficient and proper sanitary arrangements, for every worker who resides on the place of employment and for such other employees who reside on the place of employment. Such house accommodation, water supply and sanitary arrangements shall conform to such requirements and standards of health and hygiene as may be prescribed.\n\n(2) No employer shall house any worker or other person in a building the state of which or the surroundings of which are, in the opinion of the Commissioner or Health Officer, such as to endanger the health of such worker or other person and should it appear to the Commissioner or Health Officer that the accommodation provided is likely, by reason of its site, construction, size, or otherwise, to endanger the health of any worker or of any person, the Commissioner may serve the employer with an order in writing requiring him to remove, alter, enlarge or reconstruct such accommodation within a reasonable time to be stated in such order; and such order may also, if necessary, declare that no worker or other person shall be permitted to occupy any building the subject of such order pending removal, alteration, enlargement or reconstruction.\n\n(3) Should it appear to the Commissioner that accommodation ought to be provided for non-resident workers owing to their having no adequate or suitable housing of their own or by reason of the distance of their houses from the place of employment he may forbid the employment of such workers until such accommodations has been provided. Surroundings of housing to be kept clean."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A61","no":61,"noLabel":{"en":"Section 61."},"text":{"en":"A space of not less than 100 feet round any housing area shall be kept clear of jungle and secondary growth and the employer shall cause such space to be kept in a clean and sanitary condition and all refuse and excreta in or near the housing to be collected and buried or burned and shall detail a sufficient number of workers daily to carry out these duties. Regular inspection of housing."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A62","no":62,"noLabel":{"en":"Section 62."},"text":{"en":"(1) Every employer shall cause all housing to be visited and inspected not less than once a week by some responsible person who shall report to the employer if the housing is not kept clean or any refuse or excreta is allowed to accumulate in the neighbourhood of the housing and the employer shall make such arrangements as may be necessary for the cleaning of the housing and surroundings and for the removal of any refuse or excreta which may have accumulated.\n\n(2) In any case where the Commissioner or Health Officer considers that visits, inspections or other duties prescribed by subsection (1) are not satisfactorily carried out he may notify the employer accordingly, specifying the matters in respect whereof he is not satisfied, and the employer shall thereupon make such further or other arrangements, whether by substituting a different person to perform the said duties or otherwise, as the Commissioner or Health Officer may require. Separate house accommodation to be provided for each race."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A63","no":63,"noLabel":{"en":"Section 63."},"text":{"en":"On every place of employment upon which the workers employed and residing are not all of one race the employer shall, if the Commissioner so directs, provide separate house accommodation for the workers of each race. Agricultural allotments."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A64","no":64,"noLabel":{"en":"Section 64."},"text":{"en":"(1) Every employer shall set aside land suitable for allotments for the use of resident workers who have worked and resided on such place of employment for not less than 6 consecutive months and who have\n\n(2) The area of the land so set a side shall ordinarily be not less than one sixteenth of an acre for each such worker and such area shall be cleared and made available for cultivation at the expense of the employer: Provided that if the employer shall satisfy the Commissioner that any worker has failed to make proper use of the area so set aside the employer shall be relieved of his duty as aforesaid in respect of such worker.\n\n(3) The Commissioner may for good and sufficient reason by writing under his hand exempt any employer or class of employer from compliance with this section on such terms and conditions and for such period as to him may seem fit. Medical care and treatment."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A65","no":65,"noLabel":{"en":"Section 65."},"text":{"en":"(1) At every place of employment the employer shall provide for all workers such medical attention and treatment with medicines of good quality, first aid equipment and appliances for the transportation of sick or injured workers as may be prescribed.\n\n(2) Every employer shall take or cause to be taken, for treatment with as little delay as possible every worker injured or falling ill during the course of his employment and every resident worker and resident dependant on a place of employment requiring medical attention at a hospital or dispensary to the hospital or dispensary maintained for the workers at such place of employment or, if there is no such hospital or dispensary, to the nearest hospital or dispensary maintained by the Government or approved by the Commissioner and shall also provide any treatment necessary therefor.\n\n(3) The cost of maintenance and treatment of a worker and of his dependants residing on the place of employment in or at any hospital or dispensary to which the worker or his dependant is sent by the employer shall be borne or paid by the employer as long as the worker remains in his Provided that if the employer continues to pay to the worker wages or part wages amounting to not less than half his usual wages he may recover by deduction from the wages of such worker the cost of such maintenance in hospital at such rate as may be prescribed.\n\n(4) Where any such worker or dependant has been admitted to a Government hospital or dispensary, the cost of maintenance and treatment at such rate as may from time to time be prescribed and, in the event of the death of such worker or dependant in such hospital, any reasonable burial expenses incurred shall be recoverable from the employer at the suit of the Medical Officer in Charge. Burial of deceased workers or dependants."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A66","no":66,"noLabel":{"en":"Section 66."},"text":{"en":"The employer shall provide decent interment for any worker resident on a place of employment and for any dependant dying during the employment of such worker unless a relative or friend undertakes such duty. Hospital maintained by employers."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A67","no":67,"noLabel":{"en":"Section 67."},"text":{"en":"(1) The Commissioner may at any time having regard to the situation of any place of employment and the number of workers employed and resident thereon, by order in writing, require any employer to construct within a reasonable time to be stated in such order, and thereafter to maintain at his own expense, a hospital on or in the immediate neighbourhood of any place of employment upon which workers are employed by him with accommodation for such number of patients as may be stated in such order, of if there is already a hospital maintained by such employer to enlarge or add to such hospital so as to provide accommodation for a further number of patients as stated in the order; and may further require him to employ a duly registered medical practitioner to reside at and have charge of such hospital or any hospital maintained by such employer and to provide such medical practitioner with fit and proper house accommodation to the satisfaction of the Commissioner.\n\n(2) If 2 or more such places of employment are so situated that the required accommodation for patients from such places of employment can be conveniently provided in one hospital the Commissioner may, instead of ordering each employer to construct and maintain a separate hospital, order all the employers concerned to construct within a reasonable time to be stated in such order, and thereafter to maintain at their own expense one hospital hereinafter called a “group hospital” for all such places of employment with accommodation for such number of patients as may be stated in the order or if there is already a hospital erected and maintained jointly by 2 or more employers (whether constructed in pursuance of the provisions of this section or not) may order them to enlarge or add to such hospital so as to provide accommodation for such further number of patients in their employment as may be stated in the order; and may further require such employers to employ a duly registered medical practitioner to take charge of such group hospital and to provide such medical practitioner with fit and proper house accommodation to the satisfaction of the Commissioner.\n\n(3) Every employer referred to in the preceding subsection shall be responsible for the due maintenance of the group hospital as the case may be and for the provision of the staff, equipment, diet and medicines and for the observance of any rules made under this Part for the inspection and management of the hospital and the furnishing of any returns required as if the hospital were provided and maintained solely by him. workers where arrangements are inadequate."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A68","no":68,"noLabel":{"en":"Section 68."},"heading":{"en":"Approval of place of employment and prohibition of employment of"},"text":{"en":"(1) Every person intending —\n\n(a) to employ resident workers at a place of employment where workers have not hitherto been employed or have not been employed within the preceding 12 months; or\n\n(b) to increase the number of workers already employed on a place of employment so that the existing arrangement would not conform to the prescribed requirements and standards of health and hygiene, shall give notice in writing of such intention to the Commissioner.\n\n(2) If the Commissioner at any time has reason to believe that the arrangements made for the residence and employment of workers on any place of employment where it is intended that workers shall live or be employed or where workers are living or employed are from any cause inadequate for the residence and employment of such workers or of additional workers or that the health or conditions of workers living or employed on any place of employment is from any cause unsatisfactory, he may by order served on the employer prohibit the residence or employment, or both, of workers or of additional workers on such place and it shall thereupon be unlawful for any person to employ or permit to reside on such place any workers or dependants, or any workers or dependants other than those who were residing or employed thereon before the issue of such order,\n\n(3) The Commissioner may, upon being satisfied that adequate arrangements have been made for the residence and employment of the workers or of additional workers on such place of employment or that the health and condition of the workers living or employed thereon have become satisfactory, rescind the order made under subsection (2) of this section, and thereupon it shall be lawful for the employer to employ workers or additional workers as the case may be on such place of employment."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A69","no":69,"noLabel":{"en":"Section 69."},"text":{"en":"Every employer who —\n\n(a) contravenes or fails to comply with any of the provisions of section 58, 59, or 64 shall be guilty of an offence: Penalty, a fine of $600 or in default thereof imprisonment for 3 months;\n\n(b) contravenes or fails to comply with the provisions of section 60, 61, 62, 63, 65, 66, 67 or 68 shall be guilty of an offence: Penalty, a fine of $1,500 and imprisonment for 6 months;\n\n(c) contravenes or fails to comply with any order or requirements of the Commissioner or the Health Officer made under this Chapter shall be guilty of an offence: Penalty, a fine of $600 or imprisonment for 3 months. Special Provisions Relating to the Employment of Women, Young Persons and Children"}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A70","no":70,"noLabel":{"en":"Section 70."},"text":{"en":"Nothing in this Chapter or in any rule made thereunder shall apply to an industrial or other undertaking or trade or to any ship in which only members of the same family are employed, unless such employment by its nature or the circumstances in which it is carried on is dangerous to the life, health or morals of the persons employed therein. Determination of age."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A71","no":71,"noLabel":{"en":"Section 71."},"text":{"en":"The age of any person may, where the birth of such person has not been registered or the registration thereof cannot be traced, be enquired into and determined by the Commissioner and the age so determined shall be conclusive for the purposes of this Act. Certain restriction on employment of children."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A72","no":72,"noLabel":{"en":"Section 72."},"text":{"en":"No child shall be employed in any industrial undertaking: Provided that His Majesty in Council may by notification in the Gazette permit the employment of children in any specified industrial undertaking or in any specified occupation which forms part of any specified industrial Power to prohibit employment of children in other specified ways."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A73","no":73,"noLabel":{"en":"Section 73."},"text":{"en":"His Majesty in Council may by notification in the Gazette prohibit the employment of any child, or prescribe the terms and conditions on which children may be employed, in any specified trade undertaking or in any specified occupation which forms part of any specified trade or undertaking. Night work of young persons in industry."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A74","no":74,"noLabel":{"en":"Section 74."},"text":{"en":"(1) Young persons shall not be employed or work during the night in any industrial undertaking except as hereinafter provided.\n\n(2) For the purpose of this section “night” means a period of at least 12 consecutive hours —\n\n(a) in the case of young persons under the age of 16 years this period shall include the interval between 10 o’clock in the evening and 6 o’clock in the morning;\n\n(b) in the case of young persons who have attained the age of 16 years this period shall include an interval to be prescribed of at least 7 consecutive hours falling between 10 o’clock in the evening and 7 o’clock in the morning. Different intervals may be prescribed for different areas, industrial undertakings or branches of industrial Provided that before an interval beginning after 11 o’clock in the evening is prescribed the employers’ and workers’ organisations concerned, if any, shall be consulted.\n\n(3) For the purposes of apprenticeship or vocational training the Commissioner may authorise the employment during the night of young persons who have attained the age of 16 years, under such conditions as he may impose.\n\n(4) Every employer shall grant to young persons, employed during the night by virtue of the preceding subsection, a rest period of at least 13 consecutive hours between 2 working periods.\n\n(5) The provisions of this section shall not apply to employment during the night of young persons who have attained the age of 16 years, in an emergency which could not have been controlled or foreseen, which is not of a periodical character and which interferes with the normal working of the industrial undertaking. Females not to be employed at night in industry."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A75","no":75,"noLabel":{"en":"Section 75."},"text":{"en":"(1) No female shall be employed during the night in any industrial\n\n(2) For the purpose of this section “night” means a period of at least 11 consecutive hours including an interval to be prescribed of at least 7 consecutive hours falling between 10 o’clock in the evening and 7 o’clock in the morning. Different intervals may be prescribed for different areas, industrial undertakings or branches of industrial undertakings: Provided that before an interval beginning after 11 o’clock in the evening is prescribed the employers’ and workers’ organisations concerned, if any, shall be consulted.\n\n(3) The provisions of this section shall not apply —\n\n(a) in an emergency which could not have been controlled or foreseen, which is not of a periodical character and which interferes with the normal working of the industrial undertaking;\n\n(b) where the work is connected with raw materials or materials in course of treatment which are subject to rapid deterioration and work during the night is necessary to preserve such materials from certain loss;\n\n(c) to a woman holding a responsible position of a managerial or technical character; and\n\n(d) to a woman employed in health and welfare services who is not ordinarily engaged in manual work."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A76","no":76,"noLabel":{"en":"Section 76."},"text":{"en":"In any serious emergency when the public interest demands it the Minister may by notification in the Gazette suspend the operation of sections 74 and 75 in so far as they affect young persons who have attained the age of 16 years and women. Register of young persons employed in industrial undertakings."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A77","no":77,"noLabel":{"en":"Section 77."},"text":{"en":"Where young persons are employed in any industrial undertakings a register of the young persons so employed, containing particulars of their ages and of the dates on which they enter or leave the service of their employer, shall be kept by such employer and shall at all times be open to inspection by the Commissioner. Restriction on employment of females and young persons underground."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A78","no":78,"noLabel":{"en":"Section 78."},"heading":{"en":"Restriction on employment of females and young persons"},"text":{"en":"(1) No young person under the age of 16 years shall be employed on underground work in any mine.\n\n(2) No female shall be employed on underground work in any mine except in the following circumstances —\n\n(a) a woman holding a position of management who does not perform manual work;\n\n(b) a woman engaged in health or welfare services;\n\n(c) a woman who in the course of her studies spends a period of training in the underground parts of a mine; or\n\n(d) a woman who may for any other reason have to enter the underground parts of a mine for the purpose of non-manual Restriction on employment of children in ships."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A79","no":79,"noLabel":{"en":"Section 79."},"text":{"en":"No child shall be employed in any ship except a ship approved by the Commissioner as a school or training ship. Restriction on employment of young persons in ships."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A80","no":80,"noLabel":{"en":"Section 80."},"text":{"en":"No young person shall be employed on work as a trimmer or stoker in any ship unless prior written approval for such employment has been given by the Commissioner. Register of young persons employed in ships."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A81","no":81,"noLabel":{"en":"Section 81."},"text":{"en":"Every master of a ship shall, if young persons are employed therein, keep a register of such persons containing particulars of their ages and of the dates on which they become or cease to be members of the crew and the register so kept shall be open to inspection by the Commissioner. Medical certificate."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A82","no":82,"noLabel":{"en":"Section 82."},"text":{"en":"(1) The employment of any child or young person on any ship shall be conditional on the production of a medical certificate attesting fitness for such work signed by a duly registered medical practitioner.\n\n(2) The continued employment at sea of any such child or young person shall be subject to the repetition of such medical examination at intervals of not more than one year and the production, after each such examination, of a further medical certificate attesting fitness for such work. Should a medical certificate expire in the course of a voyage it shall remain in force until the end of the said voyage. Maternity benefits."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A83","no":83,"noLabel":{"en":"Section 83."},"text":{"en":"(1) Every female worker shall be entitled to abstain from work during periods 4 weeks each before and after confinement and in respect of such periods, hereinafter jointly referred to as “benefit period,” to receive from her employer maternity benefit to be calculated in accordance with the provisions of the succeeding subsections of this section.\n\n(2) A female worker who has worked for the employer from whom she claims maternity benefit on not less than 180 days within the period of one year immediately preceding the notice required under section 87 shall be paid maternity benefit during the benefit period at such rate as may be\n\n(3) A female worker who has worked for the employer from whom she claims such maternity benefit on not less than 90 days within the period of 6 calendar months immediately preceding the date of the notice required under section 87 shall be paid maternity benefit during the benefit period at such rate as may be prescribed.\n\n(4) A female worker who has worked in her employment on any day during the period of 4 weeks immediately preceding her confinement shall not be entitled to any maternity benefit for that day or that part of that period which precedes that day.\n\n(5) No employer shall knowingly employ a worker at any time during the period of 4 weeks immediately following her confinement. Payments to include rest days and holidays."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A84","no":84,"noLabel":{"en":"Section 84."},"text":{"en":"Subject to the provisions of subsection (4) of section 83, payments made under subsections (2) and (3) of section 83 shall be made for every day of the benefit period including Sundays or other agreed rest days prescribed Payment of maternity benefit."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A85","no":85,"noLabel":{"en":"Section 85."},"text":{"en":"The amount of the maternity benefit shall be payable in 2 instalments; the first for the period up to and including the day of confinement to be paid within 7 days after the birth of the child and the second for the period after confinement to be paid within 7 days after the end of that period; and shall not be payable in advance. Death during benefit."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A86","no":86,"noLabel":{"en":"Section 86."},"text":{"en":"If a female worker dies during the benefit period the maternity benefit shall be payable only for the days up to and including the day of her death. Notice of confinement."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A87","no":87,"noLabel":{"en":"Section 87."},"text":{"en":"(1) A female worker may prior to her confinement give notice to her employer that she expects to be confined within one month from the date of such notice.\n\n(2) A female worker who has been confined shall within 7 days of her confinement give notice to her employer of the date on which she was confined.\n\n(3) Any female worker who omits to give notice as required by subsection (2) shall forfeit her claim for any maternity benefit to which she is entitled unless she was prevented by any sufficient cause from the giving of such notice. Permission for absence to be given by employer."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A88","no":88,"noLabel":{"en":"Section 88."},"text":{"en":"The employer shall, on receipt of a notice from a female worker under section 87, or on the fact of the confinement of a female worker otherwise coming to his knowledge, permit such worker to absent herself from work until the expiry of 4 weeks after the day of her confinement. Forfeiture of benefit."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A89","no":89,"noLabel":{"en":"Section 89."},"text":{"en":"If a female worker for any other employer after she has been permitted by her employer to absent herself under section 88 such worker shall forfeit her claim to the payment of any maternity benefit to which she would have been entitled. Appointment of nominee."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A90","no":90,"noLabel":{"en":"Section 90."},"text":{"en":"(1) A female worker who gives notice under section 87 may in such notice nominate some other person to whom her maternity benefit may be paid on her behalf and any payment of any maternity benefit made to the person so nominated shall, for the purpose of this Chapter, be deemed to be payment to the worker who nominated such person.\n\n(2) If a female worker entitled to maternity benefit under the provisions of this Chapter dies during the period for which she is entitled to such benefit the employer shall pay the amount of maternity benefit due to the person nominated or, if there is no such person, to the legal representative to such person as is approved by the Commissioner. Notice of termination of employment."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A91","no":91,"noLabel":{"en":"Section 91."},"text":{"en":"When a female worker absents herself from work in accordance with the provisions of this Chapter her employer shall not give her notice of termination of employment during such absence or so that the notice will expire during such absence. Benefit unaffected by notice of termination in specified circumstances."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A92","no":92,"noLabel":{"en":"Section 92."},"heading":{"en":"by of in"},"text":{"en":"(1) No notice of termination of employment given without sufficient cause by an employer to a female worker within a period of 3 months before her confinement shall have the effect of depriving her of any maternity benefit which but for such notice she would have been eligible to receive under this Chapter.\n\n(2) If any question arises as to whether any notice of termination of employment given under subsection (1) of this section was or was not given for sufficient cause it shall be referred to the Commissioner for decision. Claim from one employer."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A93","no":93,"noLabel":{"en":"Section 93."},"text":{"en":"Nothing contained in section 83 shall be construed as entitling any female worker to claim maternity benefit from more than one employer in respect of the same confinement."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A94","no":94,"noLabel":{"en":"Section 94."},"text":{"en":"Any agreement or contract whereby a female worker relinquishes any right under this Chapter shall be null and void in so far as it purports to deprive her of that right or to remove or reduce the liability of any employer to pay maternity benefit under this Chapter."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A95","no":95,"noLabel":{"en":"Section 95."},"text":{"en":"Any employer who contravenes or fails to comply with any of the provisions of this Chapter, or any person who makes an entry in a register, required to be kept under the provisions of section 77 or 81, which he knows or has reason to believe to be false shall be guilty of an offence: Penalty, a fine of $1,500 or in default thereof imprisonment for 6 months."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A96","no":96,"noLabel":{"en":"Section 96."},"heading":{"en":"Rights and obligations of worker and employer in respect of"},"text":{"en":"(1) Every worker who is a party to an agreement or contract under this Act and who has been brought to the place of employment by an employer or by any person acting on behalf of the employer shall have the right to be repatriated at the expense of the employer to his place of origin or to the place of engagement, if the latter be nearer to the place of employment and the laws of the place of engagement permit, in the following cases —\n\n(a) on the termination of the agreement or contract by expiry of the period for which it was made;\n\n(b) on the termination of the agreement or contract by reason of the inability of the employer to fulfil the agreement or contract;\n\n(c) on the termination of the agreement or contract by reason of inability of the worker to fulfil the agreement or contract owing to sickness or accident;\n\n(d) on the termination of the agreement or contract by notice but in the case of a contract subject to the provisions of the particular contract and Chapter V of this Act;\n\n(e) on the cancellation of the agreement or contract under section 15 or 28;\n\n(f) on the termination of the agreement or contract by agreement between the parties, unless the Commissioner otherwise decides.\n\n(2) Every who is ordered to Brunei Darussalam under or in accordance with any provision of any written law for the time being in force relating to immigration shall be repatriated at the expense of the employer to his place of origin or to the place of engagement, if the latter be nearer to the place of employment and the laws of the place of engagement permit.\n\n(3) Where any dependant of the worker has been brought to the place of employment by the employer or by any person acting on behalf of the employer such dependant shall be repatriated at the expense of the employer whenever the worker is repatriated or in the event of his death.\n\n(4) The expenses of repatriation shall include —\n\n(a) travelling and subsistence expenses during the journey;\n\n(b) subsistence expenses during the period if any, between the date of termination of the agreement or contract and the date of repatriation; and\n\n(c) provision of decent interment and the payment of the reasonable expenses of burial in the event of death of a worker occurring during the course of, or pending, repatriation.\n\n(5) The employer shall not be liable for subsistence expenses in respect of any period during which the repatriation of the worker has been delayed —\n\n(a) by the worker’s own choice; or\n\n(b) for reasons of force majeure, when the employer has been able during the said period to use the services of the worker at the rate of wages stipulated in the expired contract.\n\n(6) If the employer fails to fulfil his obligation in respect of repatriation the said obligation shall be discharged by or under directions of the Commissioner and any sums so expended may be recovered from the employer or employers by civil suit as a debt due to the Government. Exemption from obligation to repatriate."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A97","no":97,"noLabel":{"en":"Section 97."},"text":{"en":"The Commissioner may exempt the employer from liability for repatriation expenses in the following cases —\n\n(a) when the Commissioner is satisfied —\n\n(i) that the worker by a declaration before the Commissioner has signified that he does not wish to repatriation; and\n\n(ii) that the worker has been settled at his request or with his consent at or near the place of employment;\n\n(b) when the Commissioner is satisfied that the worker by his own choice has failed to exercise his right of repatriation before the expiry of 6 months from the date of termination of the agreement or\n\n(c) when the liability of the employer has been provided for under any of the provisions of any Fund established under paragraph (c) of subsection (2) of section 121;\n\n(d) when the agreement or contract has been terminated otherwise than by reason of the inability of the worker to fulfil the agreement or contract owing to sickness or accident and the Commissioner is satisfied —\n\n(i) that in fixing the rates of wages proper allowance has been made for the payment of repatriation expenses by\n\n(ii) that suitable arrangements have been made by means of a system of deferred pay or otherwise to ensure that the worker has the funds necessary for the payment of such expenses. Employer to provide transport."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A98","no":98,"noLabel":{"en":"Section 98."},"heading":{"en":"Domestic Service"},"text":{"en":"(1) The employer shall whenever possible provide transport for workers who are being repatriated.\n\n(2) The Commissioner shall take all necessary measures to ensure and may give such directions to the employer or to any person acting on behalf of the employer as will ensure —\n\n(a) that all vehicles or vessels used for transport of workers are suitable for such transport, are in good sanitary condition and are not overcrowded;\n\n(b) that when it is necessary to break the journey for the night suitable accommodation is provided for the workers;\n\n(c) that when the workers have to make long journeys on foot the length of the daily journey is compatible with the maintenance of their health and strength; and\n\n(d) that in the case of long journeys suitable arrangements are made for medical assistance and for the welfare of the workers.\n\n(3) When the workers have to make long journeys in groups they shall be convoyed by a responsible person to be approved by the"}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A99","no":99,"noLabel":{"en":"Section 99."},"text":{"en":"Any employer who fails to comply with the direction given to him by the Commissioner in pursuance of the provisions of section 98 shall be guilty of an offence: Penalty, a fine of $600 or in default thereof imprisonment for 3 Domestic servants."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A100","no":100,"noLabel":{"en":"Section 100."},"heading":{"en":"General Provisions Relating to Agreements and Contracts"},"text":{"en":"His Majesty in Council may from time to time make rules applying all or any of the provisions of this Act to all domestic servants or to any group, class or number of domestic servants and make rules not inconsistent with any of the provisions of this Act to provide generally for the engagement, repatriation and working conditions of domestic servants. Worker not liable for default of another."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A101","no":101,"noLabel":{"en":"Section 101."},"text":{"en":"No worker shall be bound in or by virtue of any agreement or contract under this Act to answer for the debt, default or miscarriage of another Liability of worker for advances."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A102","no":102,"noLabel":{"en":"Section 102."},"text":{"en":"(1) An advance of wages to worker or to a person in consideration of his taking up employment as a worker shall not without the previous permission of the Commissioner exceed an amount equivalent to the wages earned by the worker during the previous month or if he has been employed for that period the wages he is likely to earn during one month or an amount authorised by rule under Chapter IX.\n\n(2) No worker shall be held to be liable for the amount of any advance made to him by his employer which exceeds the amount authorised under subsection (1).\n\n(3) No worker shall be held to be liable for the amount of any moneys expended on his behalf prior to his arrival in Brunei Darussalam in consideration of his engagement to work within Brunei Darussalam, other than an advance of wages as authorised by rule under Chapter IX.\n\n(4) Any advance of wages may be recovered in instalments by deduction from wages in such manner as may be prescribed. Prescribed holidays."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A103","no":103,"noLabel":{"en":"Section 103."},"text":{"en":"Holidays may be prescribed for workers. Such holidays may be fixed having regard to the religion and customs of workers. Days and hours of work."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A104","no":104,"noLabel":{"en":"Section 104."},"text":{"en":"Subject to any provisions to the contrary contained in his contract —\n\n(a) no worker other than a shift worker shall be required to work on a prescribed holiday or on more than 6 days in one week or for more than 6 consecutive hours without a break, or for more than 8 hours a day of actual work: Provided that any worker on a prescribed holiday or for more than 8 hours in any day, or for more than 6 consecutive hours in the case of accident, actual or threatened, or in case of urgent work to be done to machinery, or in case of an interruption of work which it was impossible to foresee and which is not of a recurring character, but only in so far as may be necessary to avoid serious interference with the ordinary working of the undertaking concerned;\n\n(b) if any worker works for and at the request of his employer on a prescribed holiday or on a Friday (or other agreed rest day substituted for a Friday by agreement between the employer and the worker entered into not less than 3 days before such rest day is taken) or for more than 8 hours in any day he shall be paid wages for such extra work at the following rates —\n\n(i) on prescribed holidays, at a rate of not less than double his ordinary rate of pay, but in such case wages shall not be payable under the provisions of section 103;\n\n(ii) on Friday or other rest days, at a rate of not less than one and a half times his ordinary rate of pay; and\n\n(iii) for overtime in excess of 8 hours in any one day for workers other than those paid on piece work or shift work, at a rate of not less than one and a half times his ordinary rate of pay;\n\n(c) a shift worker may be required by his employer to work for any number of hours not exceeding 56 in any one week and not exceeding 12 in any one day: Provided that where a shift worker is required to work for more than 48 hours in any one week, the average number of hours for which he may be required to work in that week and the next preceding and next succeeding week shall not, except with the approval of the Commissioner, exceed 48 hours;\n\n(d) the provisions of this section shall not apply to workers engaged in work which by its nature involves long and regular hours of inactive or standby employment; and\n\n(e) for the purposes of this section the Commissioner, in the event of any dispute, may, and shall if so required by either party to the dispute, decide whether or not any worker is a shift worker."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A105","no":105,"noLabel":{"en":"Section 105."},"text":{"en":"(1) An employer and a worker may agree to the assignment of a task to be performed by the worker as equivalent to work for a day of 8 hours and the performance of such task shall, for the purposes of this Act, be equivalent to working for a day.\n\n(2) Nothing in this Chapter contained shall prevent any employer from agreeing with any worker in his employment that the wages of such worker shall be paid at an agreed rate in accordance with the amount of work done and not by the day."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A106","no":106,"noLabel":{"en":"Section 106."},"text":{"en":"Every employer shall keep in some conspicuous position on the place of employment, so that it shall be readily accessible to the workers there employed, a Working Board on which, at intervals not exceeding 2 days, in a language understood by the workers shall be shown —\n\n(a) the wage rate, whether by day, hour, piece, task or otherwise of each worker;\n\n(b) the amount earned, including overtime payments each day by each worker;\n\n(c) the amount of any deductions made from the earnings of each worker: Provided that if any record, check roll or other document maintained by an employer as part of the routine of the place of employment gives the particulars required to be shown on a Working Board or required to be shown in a register or registers in accordance with the provisions of section 59 and that such record, check roll or other document is readily accessible to all of the workers employed by him, such record, check roll or other document may, to the corresponding extent, be maintained in place of and be treated as a Working Board for the purposes of this section. Period for which wages payable."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A107","no":107,"noLabel":{"en":"Section 107."},"text":{"en":"Unless the agreement or contract otherwise stipulates, and subject to the provisions of section 104, wages shall only be payable for days actually worked, for prescribed holidays, for days other than Sundays or other rest days on which through no fault of the worker no work is provided by the employer and for time spent in attending before any court if such court certifies that his attendance was necessary for the ends of public justice."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A108","no":108,"noLabel":{"en":"Section 108."},"text":{"en":"(1) The wages of a worker payable monthly shall be paid not later than 10 days after the expiration of the period in respect of which they are due.\n\n(2) All wages due to a worker whose agreement or contract is terminated by expiry of the period for which it was made shall be paid to him on the day on which such agreement or contract terminates.\n\n(3) All wages due to a worker whose agreement or contract is terminated by his employer shall be paid to him on the day on which such agreement or contract is terminated or if this is not possible, on the first day, not being a rest day or prescribed holiday, after the day on which such agreement or contract is terminated.\n\n(4) All wages due to a worker who terminates his agreement or contract with his employer after he has given due notice to such employer as required under section 12 or 27 shall be paid to him on the day on which such agreement or contract is terminated.\n\n(5) If a worker terminates his agreement or contract without giving notice to his employer as required by section 12 or by the terms of any contract or if the required notice having been given the worker terminates his agreement or contract without waiting for the expiry of such notice, all wages due shall be paid to him before the expiry of the tenth day after the day on which he terminates his agreement or contract: Provided that the employer may, subject to any order made by a court or the Commissioner to the contrary, deduct from the wages due to the worker such sum as the worker is liable to pay in lieu of notice according to the provisions of section 13 or the terms of his contract, if any. Payment through overseer or in shops etc. prohibited."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A109","no":109,"noLabel":{"en":"Section 109."},"text":{"en":"(1) No wages shall be paid to any worker —\n\n(a) through the agency of any overseer; or\n\n(b) at or within any shop or store; or\n\n(c) at any place or premises where intoxicating liquors are sold, except with the prior approval of the Commissioner.\n\n(2) The payment of wages where made in cash shall be made on a working day only and at or near the work place, except as may be otherwise prescribed or provided for by collective agreement, arbitration award or where other arrangements known to the workers concerned are considered more appropriate. Wages to be paid in legal tender."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A110","no":110,"noLabel":{"en":"Section 110."},"text":{"en":"Except where otherwise expressly prescribed the entire amount of the wages earned by, or payable to, any worker in respect of any work done by him shall be actually paid to him in legal tender and every payment of, or on account of, and such wages made in any other form shall be illegal, null and void."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A111","no":111,"noLabel":{"en":"Section 111."},"heading":{"en":"Agreements and contracts to pay wages otherwise than in legal tender"},"text":{"en":"In all agreements and contracts for the employment of any worker or for the performance by any worker of any work, the wages of such worker shall be made payable in legal tender and not otherwise and in any agreement or contract the whole or any part of such wages shall be made payable in any other manner such agreement or contract shall be illegal, null and void. Stipulation as to place and manner of spending wages illegal."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A112","no":112,"noLabel":{"en":"Section 112."},"text":{"en":"No employer shall impose in any agreement or contract for the employment of any worker any terms as to the place at which, or the manner in which, or the person with whom, any wages paid to the worker are to be expended and every agreement or contract between an employer and a worker containing such terms shall be illegal, null and void. Deductions and workers’ right to recover wages."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A113","no":113,"noLabel":{"en":"Section 113."},"text":{"en":"(1) No deductions shall be made by an employer from the wages of a worker otherwise than in accordance with the provisions of this Act or of any other written law.\n\n(2) The following deductions may be made from the wages of a\n\n(a) deductions made at the request in writing of the worker in respect of the payment to any superannuation scheme lawfully established for the benefit of the worker and approved by the\n\n(b) deductions made at the request in writing of the worker for the purpose of remittance by the employer to a specified member of the family of the worker;\n\n(c) deductions of any overpayment made during the immediately preceding 3 months by the employer to the worker by the employer’s mistake;\n\n(d) deductions for the recovery of advances made in accordance with the provisions of subsection (4) of section 102 and for the cost of maintenance in hospital of the workers or any dependant incurred pursuant to the provisions of subsection (3) of section 65;\n\n(e) deductions for goods and services (including dwellinghouses) provided for the benefit of and with the consent of, the worker and approved by the Commissioner; and\n\n(f) with the consent of the worker and subject to the approval of the Commissioner deductions for damage to or loss of goods entrusted to a worker for custody if such damage or loss is directly attributable to his neglect or default.\n\n(3) The total of any deductions made under this section from the wages of a worker in respect of any one month shall not exceed 50% of the wages earned by the worker during that period.\n\n(4) Every worker shall be entitled to recover in the courts of Brunei Darussalam so much of his wages exclusive of sums lawfully deducted in accordance with the provisions of this Act or any rules made thereunder as shall not have been actually paid to him in legal tender. Interest on advances forbidden."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A114","no":114,"noLabel":{"en":"Section 114."},"text":{"en":"No employer shall make any deduction by way of discount, interest or any similar charge on account of any advance of wages made to any worker. Deductions for fines etc."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A115","no":115,"noLabel":{"en":"Section 115."},"text":{"en":"Except where otherwise expressly permitted by the provisions of this Act or any rule made thereunder no employer shall make any deduction or make any agreement or contract with a worker for any deduction from wages to be paid by the employer to the worker or for any payment to the employer by the worker for or in respect of any fine, or of bad or negligent work or of injury to the materials or other property of the employer. Remuneration other than wages."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A116","no":116,"noLabel":{"en":"Section 116."},"text":{"en":"Nothing in this Chapter or in any rule made thereunder shall render illegal an agreement or contract with a worker for giving to him food, a dwelling place or other allowances or privileges in addition to money wages as a remuneration for his services but so that no employer shall give to a worker any intoxicating liquor by way of such remuneration: Provided that such legal allowances are with the consent of the worker and approved by the Commissioner, both as to suitability for the personal use and benefit of the worker and his family and the monetary value attributed to such allowances."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A117","no":117,"noLabel":{"en":"Section 117."},"text":{"en":"(1) Nothing in this Chapter or in any rule made thereunder shall prevent an employer with the approval in writing of the Commissioner, which may at any time be revoked, from establishing a shop for the sale of rice and provisions generally to his workers at prices to be approved by the Commissioner and marked or exhibited in such manner as he may require but such employer shall not compel any worker to purchase rice or such provisions at such shop.\n\n(2) No employer shall trade with any worker or establish or keep a shop on any place of employment otherwise than in accordance with the preceding subsection.\n\n(3) No person employed on any place of employment as an assistant or overseer shall traffic with any worker employed under or together with him or shall such person be either directly or indirectly financially concerned in the management of any shop wheresoever it be situated which is used or maintained for the purpose of supplying commodities of any kind whatsoever to those employed under or together with such person: Provided that nothing in this subsection shall prevent the establishment, under the law for the time being in force relating to societies or co-operative societies, of any co-operative society. Employment of immigrant workers."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A118","no":118,"noLabel":{"en":"Section 118."},"text":{"en":"(1) No person shall knowingly employ any immigrant worker unless he has obtained a licence from the Commissioner to do so in such form and subject to such conditions as may be prescribed unless such worker has been brought before the Commissioner for the purpose of subsection (2) of section 50: [S 25/90] Provided that where an immigrant worker is found at any premises or place and is in possession of any tools or other implements or is engaged in any activity which may give rise to the inference that he is doing any work, the occupier of such premises or place shall, until the contrary is proved, be presumed to have employed him knowing that he is an immigrant worker. [S 25/90]\n\n(2) In subsection (1), “occupier”, in relation to any premises or place, includes —\n\n(a) the person having the charge, management or control of either the whole or part of the premises or place, either on his own account or as an agent; and\n\n(b) a contractor who is carrying out building operations or construction works at the premises or place on behalf of some other [S 25/90]\n\n(3) Any employer who contravenes the provisions of subsection (1) and any immigrant worker found working for such an employer shall each be guilty of an offence: Penalty, a fine of $10,000 and imprisonment for a term of not less than 6 months and not more than 3 years. [S 25/90]\n\n(4) In subsection (3), “employer” includes a person who has entered into an engagement for money or money’s worth for another person to work\n\n(a) that other person is already under an agreement or contract with an employer (as defined in section 2) and in respect of whom a licence has been contained by such employer from the Commissioner under subsection (1); or\n\n(b) the work is at piece rates or on commission, whether or not as the result of an arrangement with an employer (as defined in [S 25/90] Exemption of employer if not actual offender."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A119","no":119,"noLabel":{"en":"Section 119."},"text":{"en":"(1) When an employer is charged with an offence against this Chapter or any rule made thereunder he shall be entitled, upon information duly laid by him, to have any other person whom he charges as the actual offender brought before the court at the time appointed for hearing the charge and if, after the commission of the offence has been proved, the employer shall prove to the satisfaction of the court that he has used due diligence to enforce the provisions of this Chapter and that the said other person has committed the offence in question without his knowledge, consent or connivance, the said other person shall be liable to be summarily convicted of such offence and in such case the employer shall be exempt from any\n\n(2) When it appears to the Commissioner at the time of discovering an offence that the employer has used due diligence to comply with the provisions of this Chapter or any rule made thereunder and that the person who committed the offence did so without knowledge, consent or connivance of the employer, then the Commissioner may proceed against that person in the first instance without first proceeding against the employer."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A120","no":120,"noLabel":{"en":"Section 120."},"text":{"en":"Any employer who —\n\n(a) requires any worker to work on any occasion or under any circumstances in which it is unlawful for him to require such worker to work; or\n\n(b) fails to pay wages in accordance with the provisions of this Chapter; or\n\n(c) give any remuneration for services contrary to the provisions of this Chapter, or makes any deduction from the wages of any worker or receives any payment from any worker contrary to the provisions of this Chapter; or\n\n(d) trades with his worker or keeps a shop otherwise than in accordance with the provisions of this Chapter; or\n\n(e) contravenes or fails to comply with any order of the Commissioner made under this Chapter, and any person employed on a place of employment who contravenes the provisions of subsection (3) of section 117 shall be guilty of an offence: Penalty, a fine of $1,500 or in default thereof imprisonment for 6 months. Power to make rules."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A121","no":121,"noLabel":{"en":"Section 121."},"text":{"en":"(1) His Majesty in Council may from time to time make rules generally for carrying out the provisions of this Part.\n\n(2) Without prejudice to the generality of the foregoing power such rules may —\n\n(a) provide for any matter which by this Part is to be or may be\n\n(b) prescribe in respect of place of employment to which Chapter X has been applied —\n\n(i) the form and siting of latrines and the arrangements to be made for disposal of night soil;\n\n(ii) the steps to be taken for the control of malaria, including the administration of prophylactics;\n\n(iii) the steps to be taken for the protection and adequacy of the water supply; and\n\n(iv) the requirements for inspection and management of hospitals;\n\n(c) provide for the establishment of a fund or other method of securing the discharge of any liabilities and the expenses of repatriation of workers upon such terms and conditions and subject to such control as he deems necessary and for the administration of such a fund in conjunction with any fund established under the provisions of paragraph (l) of subsection (1) of section 56;\n\n(d) prescribe the fees to be paid and by whom payable for any licences issued, attestations, endorsements or registration effected or any other acts required to be done in pursuance of the provisions of this Act or any rules made thereunder.\n\n(3) Any rule may provide a penalty for the breach or contravention thereof not exceeding a fine of $600 or in default thereof imprisonment for a term not exceeding 3 months.\n\nPROCEDURE AND SAVINGS Costs of proceedings."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A122","no":122,"noLabel":{"en":"Section 122."},"chapter":{"en":"PART V"},"text":{"en":"No court fees shall be chargeable in the first instance on any proceeding commenced by a worker, or by the Commissioner on his behalf, against his employer under this Act; but in case a conviction shall be had or judgement given against the employer, the same shall be paid by the employer, together with the general costs of the proceeding. Convictions and penalties."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A123","no":123,"noLabel":{"en":"Section 123."},"chapter":{"en":"PART V"},"text":{"en":"(1) Subject to any special provisions to the contrary contained in the Act, all convictions and penalties for offences under this Act may be had and recovered before a Court of a Magistrate on complaint by any person aggrieved or by the Commissioner or any person authorised by him in that\n\n(2) Any such Court may, notwithstanding anything contained in any written law to the contrary, impose the full punishment prescribed by this Act."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A124","no":124,"noLabel":{"en":"Section 124."},"chapter":{"en":"PART V"},"text":{"en":"The Commissioner and any officer authorised by him in writing shall have the right to appear and be heard before any Court in any proceedings under this Act instituted by him."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A125","no":125,"noLabel":{"en":"Section 125."},"chapter":{"en":"PART V"},"text":{"en":"For the purposes of this Act and of the Penal Code (Chapter 22), the Commissioner and all officers duly appointed or authorised under this Act shall be deemed to be public servants."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A126","no":126,"noLabel":{"en":"Section 126."},"chapter":{"en":"PART V"},"text":{"en":"For the purposes of sections 159 and 510 of the Penal Code (Chapter 22), every state, factory, mine or place of employment in which 10 or more workers are employed shall be deemed to be a public place. Enactment no bar to civil suit."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A127","no":127,"noLabel":{"en":"Section 127."},"chapter":{"en":"PART V"},"text":{"en":"Nothing in this Act shall operate to prevent any employer or worker from enforcing their respective civil rights and remedies for any breach or non-performance of an agreement or contract by any suit in Court in any case which proceedings are not instituted or if instituted are not proceeded with to judgement and satisfaction under this Act."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A128","no":128,"noLabel":{"en":"Section 128."},"chapter":{"en":"PART V"},"text":{"en":"In all proceedings under this Act the onus of proving that he is not the employer or the person whose duty it is under this Act or under any rule made thereunder to do or abstain from doing anything shall be on the person who alleges that he is not the employer or other person as the case may be. Service of summons."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A129","no":129,"noLabel":{"en":"Section 129."},"chapter":{"en":"PART V"},"text":{"en":"(1) A summons issued by the Commissioner in accordance with section 6 may be served on any person by delivering or tendering to him a copy thereof signed by the Commissioner:\n\n(a) if the person to be summoned has an agent authorised to accept service of the summons on his behalf, service on such agent shall be sufficient;\n\n(b) if the person to be summoned cannot be found and has no agent authorised to accept service of the summons on his behalf, service on any adult male member (not being a servant) of the family of the person to be summoned who is residing with him shall be sufficient.\n\n(2) When such summons as aforesaid is addressed to a company it may be served —\n\n(a) by leaving a copy thereof signed by the Commissioner, at the registered office, if any, of the company; or\n\n(b) by sending such copy by post in a letter addressed to the company at its principal office, whether such office is situated within Brunei Darussalam or elsewhere; or\n\n(c) by delivering such copy to any director, secretary or other principal officer of the company.\n\n(3) When the serving officer delivers or tenders a copy of the summons to the person to be summoned or to any agent or other person to be summoned or to an agent or other person on his behalf, he shall require the signature of the person to whom the copy is so delivered or tendered to an acknowledgement of service endorsed on the original summons.\n\n(4) If —\n\n(a) such refuses or is to sign the acknowledgement; or\n\n(b) the serving officer cannot find the person to be summoned and there is no agent empowered to accept service of the summons on his behalf nor any other person on whom the service can be made, the serving officer shall affix a copy of the summons on the outdoor of the house in which the person to be summoned ordinarily resides and then return the original to the Commissioner with a return endorsed thereon or annexed thereto stating that he has so affixed the copy and the circumstances under which he did so.\n\n(5) The serving officer shall, in all cases in which the summons has been served under subsection (3) of this section endorse or annex, or cause to be endorsed or annexed, on or to the original summons a return stating the time when and the manner in which the summons was served.\n\n(6) When the summons is returned under subsection (4) of this section, the Commissioner shall, if the return under that subsection has not been verified by the affidavit of the serving officer, and may if it has been so verified, examine the serving officer on affirmation touching his proceedings and may make such further enquiry in the matter as he thinks fit and shall either declare that the summons has been duly served or order such service as he thinks fit.\n\n(7) When the Commissioner is satisfied that there is reason to believe that the person to be summoned is keeping out of the way for the purpose of avoiding service or that for any other reason cannot be served in the ordinary way, the Commissioner may order the summons to be served by affixing a copy thereof in some conspicuous place or near the office of the Commissioner and also upon some conspicuous part of the house, if any, in which the person to be summoned is known to have resided, or in such other manner as the Commissioner thinks fit.\n\n(8) The service substituted by order of the Commissioner shall be as effectual as if it had been made personally on the person to be summoned.\n\n(9) Whenever service is substituted by order of the Commissioner, the Commissioner shall fix such time for the appearance of the person to be summoned as the case may require.\n\n(10) Any order or notice in writing made or issued by the Commissioner or the Health Officer in the exercise of powers conferred by this Act may be served as if the same were a summons, and the provisions of this section, other than subsection (9) of this section, shall apply to the service of any such order or notice. Application of fines."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A130","no":130,"noLabel":{"en":"Section 130."},"chapter":{"en":"PART V"},"text":{"en":"When under this Act any court imposes a fine the court may, if it thinks fit, direct that the whole or any part of such fine or sum when recovered by paid to the aggrieved party. Existing Acts not affected."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A131","no":131,"noLabel":{"en":"Section 131."},"chapter":{"en":"PART V"},"text":{"en":"Nothing in this Act shall operate to relieve any employer of any duty or liability imposed upon him by the provisions of any other Act for the time being in force or to limit any powers given to any Government officer by any such Act. Existing agreements etc. not affected."}},{"id":"BN-CAP-93-2002-LABOUR-ACT-A132","no":132,"noLabel":{"en":"Section 132."},"chapter":{"en":"PART V"},"heading":{"en":"___________________________"},"text":{"en":"All agreements and contracts entered into between any employer and any worker, valid and in force on the date of the commencement of this Act shall continue to be in force after such date and, subject to the express provisions contained in any such agreement or contract, the parties thereto shall be subject to and entitled to the benefit of the provisions of this Act."}}],"pack":"bn-p24","summary":{"en":"An Act to amend and consolidate the law relating to labour"},"titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"LABOUR ACT","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-CAP-93-R1-2002-LABOUR-LIMITATION-OF-DUTIES-AND-POWER-RULES"] = {"id":"BN-CAP-93-R1-2002-LABOUR-LIMITATION-OF-DUTIES-AND-POWER-RULES","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":2,"structureMode":"SECTION","title":{"zh":"R1 2002 版劳动（职责与权力限制）规则","en":"R1 2002 ED LABOUR LIMITATION OF DUTIES AND POWER RULES","orig":"R1 2002 ED LABOUR LIMITATION OF DUTIES AND POWER RULES","vi":"Quy tắc Lao động: giới hạn nhiệm vụ và quyền hạn","th":"ข้อกำหนดแรงงาน: การจำกัดหน้าที่และอำนาจ","id":"Peraturan Ketenagakerjaan: Pembatasan Tugas dan Wewenang","ms":"Kaedah Buruh: Had Tugas dan Kuasa"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《CAP-93-R1-2002-ED-LABOUR-LIMITATION-OF-DUTIES-AND-POWER-RULES.pdf》（6 页），本次切分 2 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"CAP-93-R1-2002-ED-LABOUR-LIMITATION-OF-DUTIES-AND-POWER-RULES.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-CAP-93-R1-2002-LABOUR-LIMITATION-OF-DUTIES-AND-POWER-RULES-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"These Rules may be cited as the Labour (Limitation of Duties and Powers) Rules. Limitation of Duties and Powers."}},{"id":"BN-CAP-93-R1-2002-LABOUR-LIMITATION-OF-DUTIES-AND-POWER-RULES-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Limitation of Duties and Powers. __________________________ Rules under section 3(1) prescribing limitations upon the exercise of powers by certain officers LABOUR (LIMITATION OF DUTIES AND POWERS) RULES"}}],"pack":"bn-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"R1 2002 ED LABOUR LIMITATION OF DUTIES AND POWER RULES","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-CAP-93-R5-2002-LABOUR-PUBLIC-CONTRACTS-RULES"] = {"id":"BN-CAP-93-R5-2002-LABOUR-PUBLIC-CONTRACTS-RULES","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":11,"structureMode":"SECTION","title":{"zh":"R5 2002 版劳工公共合同规则","en":"R5 2002 ED LABOUR PUBLIC CONTRACTS RULES","orig":"R5 2002 ED LABOUR PUBLIC CONTRACTS RULES","vi":"Quy tắc Lao động: hợp đồng công","th":"ข้อกำหนดแรงงาน: สัญญาจ้างภาครัฐ","id":"Peraturan Ketenagakerjaan: Kontrak Publik","ms":"Kaedah Buruh: Kontrak Awam"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《CAP-93-R5-2002-ED-LABOUR-PUBLIC-CONTRACTS-RULES.pdf》（8 页），本次切分 11 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"CAP-93-R5-2002-ED-LABOUR-PUBLIC-CONTRACTS-RULES.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-CAP-93-R5-2002-LABOUR-PUBLIC-CONTRACTS-RULES-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"These Rules may be cited as the Labour (Public Contracts) Rules."}},{"id":"BN-CAP-93-R5-2002-LABOUR-PUBLIC-CONTRACTS-RULES-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"In these Rules, unless the context otherwise requires — “Government” means the Government of Brunei Darussalam and includes such Public Authorities, Municipal Boards or local authorities as the Minister may from time to time specify; “Public contract” means any contract which fulfils the following conditions —\n\n(a) that one party to the contract is the Government or has entered into the contract with assistant from the Government by way of grant, loan, subsidy, licence, guarantee or other similar form of assistance;\n\n(b) that the execution of the contract involves —\n\n(i) the expenditure of Government funds; and\n\n(ii) the employment of workers by the other party to the contract;\n\n(c) that the contract is a contract for —\n\n(i) the construction, alteration, repair or demolition of public works; or\n\n(ii) the manufacture, assembly, handling or shipment of materials, supplies or equipment; or\n\n(iii) the performance or supply of services;\n\n(d) that the contract is awarded by a duly authorised officer of the\n\n(e) that the contract involves the expenditure of Government funds of an amount of not less than $10,000. Terms and condition of public contracts set out in the Schedule."}},{"id":"BN-CAP-93-R5-2002-LABOUR-PUBLIC-CONTRACTS-RULES-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"There shall be implied in every public contract entered into on or after the commencement of these Rules the terms and conditions set out in the Schedule hereto and it shall be the duty of every contractor who enters into any such contract to observe and comply with such terms and conditions in the execution of such contract.\n\nTERMS AND CONDITIONS"}},{"id":"BN-CAP-93-R5-2002-LABOUR-PUBLIC-CONTRACTS-RULES-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"Before being allowed to tender for any public contract the contractor shall certify that to the best of his knowledge and belief the wages, hours of work and conditions of work of all workers employed by him in the trade or industry in which he is offering himself as a contractor are fair and reasonable having regards to the provisions of this Schedule."}},{"id":"BN-CAP-93-R5-2002-LABOUR-PUBLIC-CONTRACTS-RULES-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"In the event of any differences or dispute arising (as to what wages ought to be paid, or what hours or other working conditions ought to be observed in accordance with the provisions of this Schedule, it shall, if not otherwise disposed of, be referred by the Commissioner of Labour to an independent tribunal, for decision. In arriving at its decision the tribunal, in the absence of any established rates and conditions in the trade or industry concerned as specified in paragraph 1 of this Schedule, shall have regard to any agreement, custom practice or award that may be brought to its notice relating to the wages, hours or conditions of work of persons employed in a capacity similar to that of the persons to whom the difference or dispute relates in trades or industries carried on under similar general"}},{"id":"BN-CAP-93-R5-2002-LABOUR-PUBLIC-CONTRACTS-RULES-A6","no":6,"noLabel":{"en":"Section 6."},"text":{"en":"A sub-contractor shall be bound in all cases to conform to the conditions of the main contract and the main contractor shall be responsible for the observance of all contract conditions on the part of sub-contractors."}},{"id":"BN-CAP-93-R5-2002-LABOUR-PUBLIC-CONTRACTS-RULES-A7","no":7,"noLabel":{"en":"Section 7."},"text":{"en":"Contractors and sub-contractors shall recognise the freedom of their workers to be members of registered trade unions."}},{"id":"BN-CAP-93-R5-2002-LABOUR-PUBLIC-CONTRACTS-RULES-A8","no":8,"noLabel":{"en":"Section 8."},"text":{"en":"The Commissioner of Labour may require any contractor concerned in the execution of a public contract to file a certificate —\n\n(i) showing the rates of wages and hours of work of the various classes or workers employed in the execution of the public contract;\n\n(ii) whether any wages in respect of the said work remain in arrears; and\n\n(iii) that all the conditions of work of the public contract have been duly complied with."}},{"id":"BN-CAP-93-R5-2002-LABOUR-PUBLIC-CONTRACTS-RULES-A9","no":9,"noLabel":{"en":"Section 9."},"text":{"en":"The contractor shall also from time to time furnish to the Commissioner of Labour such further detailed information and evidence as the Commissioner may deem necessary in order to satisfy himself that the conditions of this Schedule have been complied with."}},{"id":"BN-CAP-93-R5-2002-LABOUR-PUBLIC-CONTRACTS-RULES-A10","no":10,"noLabel":{"en":"Section 10."},"text":{"en":"In the event of default being made in payment of any money in respect of wages of any worker employed on the public contract or in respect of any money due to such worker under any law relating to Workmen’s Compensation and if a claim thereafter is filed in the office of the Commissioner of Labour and proof thereof satisfactory to the Commissioner is furnished, the Commissioner may, failing payment, by the contractor arrange for the payment of such claim out of the monies at any time payable under the said contract and the amount so paid shall be deemed payment to the contractor."}},{"id":"BN-CAP-93-R5-2002-LABOUR-PUBLIC-CONTRACTS-RULES-A11","no":11,"noLabel":{"en":"Section 11."},"text":{"en":"Any contractor or sub-contractor who is found to be in breach of the conditions of this Schedule shall cease to be awarded contracts for such period as the Minister may determine after consultation with the Commissioner of Labour and duly authorised officer of the Government by whom the contract was awarded."}}],"pack":"bn-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"R5 2002 ED LABOUR PUBLIC CONTRACTS RULES","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
  FT["BN-CAP-93-R6-LABOUR-IMMIGRANT-WORKERS-EMPLOYMENT-LICENCES-RULES"] = {"id":"BN-CAP-93-R6-LABOUR-IMMIGRANT-WORKERS-EMPLOYMENT-LICENCES-RULES","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":5,"structureMode":"SECTION","title":{"zh":"R6 劳工移民工人就业许可证规则","en":"R6 LABOUR IMMIGRANT WORKERS EMPLOYMENT LICENCES RULES","orig":"R6 LABOUR IMMIGRANT WORKERS EMPLOYMENT LICENCES RULES","vi":"Quy tắc Lao động: giấy phép lao động cho lao động nhập cư","th":"ข้อกำหนดแรงงาน: ใบอนุญาตจ้างแรงงานต่างด้าว","id":"Peraturan Ketenagakerjaan: Izin Mempekerjakan Tenaga Kerja Asing","ms":"Kaedah Buruh: Lesen Penggajian Pekerja Pendatang"},"level":"regulation","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《CAP-93-R6-LABOUR-IMMIGRANT-WORKERS-EMPLOYMENT-LICENCES-RULES.pdf》（9 页），本次切分 5 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"CAP-93-R6-LABOUR-IMMIGRANT-WORKERS-EMPLOYMENT-LICENCES-RULES.pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-CAP-93-R6-LABOUR-IMMIGRANT-WORKERS-EMPLOYMENT-LICENCES-RULES-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"These Rules may be cited as the Labour (Immigrant Workers’ Employment Licences) Form and conditions of Licence to employ immigrant workers."}},{"id":"BN-CAP-93-R6-LABOUR-IMMIGRANT-WORKERS-EMPLOYMENT-LICENCES-RULES-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"A licence to employ immigrant workers in accordance with section 118 of the Labour Act shall be in the form of the Schedule to these Rules and shall be subject to the conditions Provided that the Commissioner of Labour may exempt any employer from any or all of the said conditions. Application for licence to employ immigrant workers."}},{"id":"BN-CAP-93-R6-LABOUR-IMMIGRANT-WORKERS-EMPLOYMENT-LICENCES-RULES-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"Every application for such licence shall be made to the Commissioner and shall be in such form as the Commissioner may require. (rule 2)\n\nLICENCE TO RECRUIT AND EMPLOY IMMIGRANT WORKERS (section 118 of the Labour Act, Chapter 93) Licence No.: ...................................... Name of Employer: ................................................................................................................... Address and Telephone Number of Employer: .................................................................................................... .................................................................................................... Industry : ................................................................................................................................... having undertaken to observe the conditions stated below, is hereby licensed to employ not (continued) more than ...................... immigrant workers as described in the Schedule hereto, as and when they shall have been duly permitted to engage in employment in Brunei Darussalam in accordance with the provisions of the Immigration Act (Chapter 17). .................................................................. Commissioner of Labour Brunei Darussalam .............................. 20 .........."}},{"id":"BN-CAP-93-R6-LABOUR-IMMIGRANT-WORKERS-EMPLOYMENT-LICENCES-RULES-A4","no":4,"noLabel":{"en":"Section 4."},"text":{"en":"The following conditions shall be deemed to be implied in every agreement with an immigrant worker employed under this licence —\n\n(1) The Employer undertakes to provide the worker with work suited to his capacity at not less than the prevailing wage for the particular type of work on which he is engaged.\n\n(2) The Employer will provide the worker and his dependants residing with him in Brunei Darussalam with housing, sanitary measures and medical care and attention (including maintenance and treatment in hospital) in the manner required by Chapter X of the Labour Act, and the said Chapter shall be deemed to apply to every place of employment where an immigrant worker is employed.\n\n(3) The Employer will, if requested, provide the worker free of charge with facilities to make remittances to his family in the country of origin or at the places of engagement.\n\n(4) The employer will, on termination of employment in the case of immigrant workers from Malaysia, repatriate them to the place of engagement if recruited outside Brunei Darussalam or if engaged locally, transport them to the Brunei Darussalam immigration post on the border of their country provided that the Commissioner may exempt (continued) the employer from repatriation and transport obligations at the request or with the consent of the worker in accordance with section 27(4) and 27(5) or section 97 of the Act. [S 6/79]\n\n(5) The employer will ensure in all cases of employment of immigrant workers, that their documents for entry and employment in Brunei Darussalam are valid at the time of engagement and during employment. [S 6/79]"}},{"id":"BN-CAP-93-R6-LABOUR-IMMIGRANT-WORKERS-EMPLOYMENT-LICENCES-RULES-A5","no":5,"noLabel":{"en":"Section 5."},"text":{"en":"This licence shall be liable to forfeiture —\n\n(1) In the event of failure to observe any of these conditions; or\n\n(2) In the event of the Employer being convicted of an offence under the Immigration Act, (Chapter 17) or any written law regulating conditions of employment; or\n\n(3) In the event of the employer being guilty of conduct which in the opinion of the Commissioner renders him no longer a fit and proper person to hold it. [S 6/79] .................................................................. (Place and date) .................................. 20 ........... No."}}],"pack":"bn-p24","titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"R6 LABOUR IMMIGRANT WORKERS EMPLOYMENT LICENCES RULES","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
