  FT["BN-E-2-OF-1939-FEDERATED-MALAY-STATES-LAWS-ADOPTION-ENAC-2B9B06"] = {"id":"BN-E-2-OF-1939-FEDERATED-MALAY-STATES-LAWS-ADOPTION-ENAC-2B9B06","coverage":"full","language":"en","sourceName":"Attorney General's Chambers, Brunei Darussalam (AGC) — LAWS OF BRUNEI / Government Gazette","sourceUrl":"","fetchedAt":"2026-10-11","articleCount":3,"structureMode":"SECTION","title":{"zh":"马来联邦法律采纳法令 1939（E 2 of 1939）","en":"E 2 OF 1939 FEDERATED MALAY STATES LAWS ADOPTION ENACTMENT 1939(1)","orig":"E 2 OF 1939 FEDERATED MALAY STATES LAWS ADOPTION ENACTMENT 1939(1)","vi":"Sắc lệnh Tiếp nhận pháp luật Liên bang Mã Lai (E 2) số 1 năm 1939","th":"คำสั่งการรับบังคับใช้กฎหมายสหพันธรัฐมลายู (E 2) ฉบับที่ 1 พ.ศ. 2482","id":"Perintah Penerimaan Hukum Negeri-Negeri Melayu Bersekutu (E 2) Nomor 1 Tahun 1939","ms":"Perintah Penerimaan Undang-Undang Negeri-Negeri Melayu Bersekutu (E 2) Bilangan 1 1939"},"level":"law","status":"active","issuingBody":"Attorney General's Chambers, Brunei Darussalam","completenessNote":"来源为 AGC 官方 PDF《E-2-OF-1939-FEDERATED-MALAY-STATES-LAWS-ADOPTION-ENACTMENT-1939(1).pdf》（2 页），本次切分 3 条。该 PDF 为扫描件 + OCR 文本层，正文按版式位置重建：已剔除页眉页脚与边栏条标题、回接折行；未改写措辞、未增删内容。OCR 层面可能存在个别粘连或形近字，逐字引用请以原始 PDF 为准。","textQuality":"ocr-scanned","sourceFile":"E-2-OF-1939-FEDERATED-MALAY-STATES-LAWS-ADOPTION-ENACTMENT-1939(1).pdf","country":"BN","countryName":"文莱","layer":"intl","articles":[{"id":"BN-E-2-OF-1939-FEDERATED-MALAY-STATES-LAWS-ADOPTION-ENAC-2B9B06-A1","no":1,"noLabel":{"en":"Section 1."},"text":{"en":"This Enactment may be cited as the Federated Malay States Laws Adoption Enactment, 1939, and shall come into force on such date as the Sultan in Council may by pu!Jlic notification appoint."}},{"id":"BN-E-2-OF-1939-FEDERATED-MALAY-STATES-LAWS-ADOPTION-ENAC-2B9B06-A2","no":2,"noLabel":{"en":"Section 2."},"text":{"en":"Subject to the provisions of all other laws for the time being in force in the State and to the provisions ot Section 3 of this Enactment the Jaws of the Federated Malay States set forth in the First Schedule hereto together with all legislative provisions of the Federated Malay States hy wh ich the said laws have been or shall be added to, repealed, or amended, shall, with such formal alterations and amendments as may be necessary to make the same applicable to the circumstances of the State, have effect within the State in the same manner as if they had been expressly enacted by the Sultan in Council"}},{"id":"BN-E-2-OF-1939-FEDERATED-MALAY-STATES-LAWS-ADOPTION-ENAC-2B9B06-A3","no":3,"noLabel":{"en":"Section 3."},"text":{"en":"- ( i) Such provisions of the said laws of the Federated Malay States as are or may from time to time be included in the Second Schedule hereto shall be excluded from the scope of this Enactment and shall not have effect 1rithin the State.\n\n(ii) The Sultan in Council may be resolution include in the Second Schedule any provision of the said laws of the Federated Malay States or may remove therefrom any provision specified therein. -l. l'pon the coming into force of this Enactment Section 25 of the Courts Enactment, 1908, shall be repealed.\n\nFIRST SCHEDVLE The Specific Relief Enactment. The Criminal Procedure Code. 7S'S FIRST SCHEDULE-continued The Civil Procedure Code. The Evidence Enactment. The Penal Code. The Contract Enactment.\n\nSECOND SCHEDULE"}}],"pack":"bn-p24","summary":{"en":"An Enactment to provide for the adoption in Brunei"},"titleTranslation":{"engine":"llm","model":"deepseek-v4.1-flash","reviewed":false,"batch":"CALR-TITLE-20261017-1801-BN-1261","source":"E 2 OF 1939 FEDERATED MALAY STATES LAWS ADOPTION ENACTMENT 1939(1)","note":"由翻译 agent 按《法规标题中译规范》产出，经 tools/verify-title-return.js 机器校验后入库；尚未人工复核。"}};
